window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[6] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(17\\)</span></span> נק׳) הוכיחו את הטענה הבאה: תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה יורדת בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> וחסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>.</span> אז קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x)\\)</span> (במובן הסופי).</p>\n<p><strong>ב.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8\\)</span></span> נק׳) הוכיחו או הפריכו את הטענה הבאה: תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה יורדת במובן החלש בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> אך אינה יורדת בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>.</span> אז קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x)\\)</span> (במובן הסופי).</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה שכל הזמן יורדת אבל יש לה רצפה שאסור לה לרדת מתחתיה, מוכרחה להתקרב אל הגבול הכי נמוך שאליו היא מסוגלת להתקרב (האינפימום).</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה שכל הזמן יורדת אבל יש לה רצפה שאסור לה לרדת מתחתיה, מוכרחה להתקרב אל הגבול הכי נמוך שאליו היא מסוגלת להתקרב (האינפימום).</p>\n<p><strong>תמונה בראש</strong>: דמיינו כדור שמתגלגל במורד מדרון אינסופי ימינה, אבל מתחת למדרון יש רצפת זכוכית שהוא לא יכול לחצות (חסימות). ככל שהולכים ימינה הכדור יורד נמוך יותר ויותר, אבל לעולם לא יורד מתחת לקומת הזכוכית הכי גבוהה שמחזיקה את כל ערכי הגרף — זו האינפימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span> אם ניקח תקרה דמיונית בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>,</span> חייב להיות מקום שבו הגרף נכנס מתחת לתקרה הזו, ובגלל שהוא רק יורד משם והלאה הוא כבר לכוד לנצח ברצועה שבין <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1+\\frac{2}{x+1}\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>).</span> היא יורדת ממש וחסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(1&lt;f(x)&lt;3\\)</span>).</span> הגבול התחתון של ערכיה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\inf\\{f(x)\\mid x&gt;0\\}=1\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=0.4\\)</span>:</span> כדי <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&lt;1.4\\)</span></span> מספיק <span class=\"math math-inline\" dir=\"ltr\">\\(M_0=4\\)</span> (כאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(4)=1.4\\)</span>,</span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;4\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1&lt;f(x)&lt;1.4\\)</span>).</span></p>\n<p><strong>חסם תחתון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\)</span>)</span></strong> של קבוצה לא-ריקה וחסומה מלרע (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span>)</span> הוא המספר הגדול ביותר שנשאר מתחת או שווה לכל איברי הקבוצה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1+\\frac{2}{x+1}\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> הירוק הוא הרצפה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=1\\)</span>.</span> הזיזו את <span class=\"math math-inline\" dir=\"ltr\">\\(v\\)</span> (מייצג את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>):</span> הקו הירוק העליון הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1+v\\)</span>.</span> משמאל לקו האדום המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{2}{v}-1\\)</span> הפונקציה עוד יורדת לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+v\\)</span>,</span> ומימין לו היא כבר נשארת כלואה בין <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+v\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:12,&quot;ymin&quot;:0.6,&quot;ymax&quot;:3.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;v&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;v=0.4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.2,&quot;max&quot;:1,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=1+\\\\frac{2}{x+1}+0\\\\cdot\\\\ln(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;L&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;Lv&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1+v&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;M0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=\\\\frac{2}{v}-1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(\\\\frac{2}{v}-1, 1+v)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מי יהיה המועמד לגבול $L$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מי יהיה המועמד לגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></p><div class=\"callout-body\"><p>הסתכלו על תמונת הפונקציה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A = \\{f(x) \\mid x \\in (a,\\infty)\\}\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה בקטע, לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> יש חסם תחתון (אינפימום) סופי <span class=\"math math-inline\" dir=\"ltr\">\\(L = \\inf A\\)</span> לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שימוש באפיון $\\varepsilon$ של האינפימום ובמונוטוניות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש באפיון <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> של האינפימום ובמונוטוניות</p><div class=\"callout-body\"><p>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span> כבר אינו חסם מלרע של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>.</span> מצאו נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M_0 &gt; a\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(M_0) &lt; L+\\varepsilon\\)</span>,</span> ושאלו מה קורה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> עבור כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר את קבוצת הערכים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A=f((a,\\infty))\\)</span>,</span> נבדוק שהיא לא ריקה וחסומה מלרע, ונסמן את קיומו של <span class=\"math math-inline\" dir=\"ltr\">\\(L=\\inf A\\in\\mathbb{R}\\)</span> לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span> (הנובע ממשפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>).</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> נמצא מאפיון האינפימום (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.14\\)</span>)</span> נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M_0&gt;a\\)</span> שבה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(M_0)&lt;L+\\varepsilon\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יורדת נסיק שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;M_0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\le f(x) &lt; L+\\varepsilon\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x)=L\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: קיום האינפימום <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> של קבוצת הערכים.</strong> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A = \\{f(x) \\mid x \\in (a,\\infty)\\}\\)</span>.</span> הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> אינו ריק (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+1 \\in (a,\\infty)\\)</span>),</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A \\ne \\emptyset\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K &gt; 0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)| \\le K\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>,</span> ובפרט <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) \\ge -K\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה מלרע. לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span> (קיום חסם תחתון, הנובע מאקסיומת השלמות — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>),</span> קיים לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסם תחתון ממשי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L := \\inf A \\in \\mathbb{R}\\)</span>.</span></p>\n<p><strong>שלב 2: הוכחת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = L\\)</span> לפי הגדרת הגבול באינסוף.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon &gt; 0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(L = \\inf A\\)</span></span> הוא החסם התחתון של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span> גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> ולכן אינו חסם מלרע של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> (אפיון האינפימום, משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.14\\)</span>).</span> לפיכך קיים איבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> הקטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>,</span></span> כלומר קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M_0 \\in (a,\\infty)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(M_0) &lt; L + \\varepsilon.\\]</div>\n<p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0 &gt; a\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; a\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יורדת בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>,</span></span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) \\le f(M_0)\\)</span> (למעשה יורדת ממש נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &lt; f(M_0)\\)</span>).</span> מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> הוא חסם מלרע של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\le f(x)\\)</span>.</span> יחדיו מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L - \\varepsilon &lt; L \\le f(x) \\le f(M_0) &lt; L + \\varepsilon,\\]</div>\n<p>ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x) - L| &lt; \\varepsilon\\)</span>.</span></p>\n<p><em>למה?</em> מרגע <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חצתה למטה את הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>,</span> הירידה מונעת ממנה לחזור למעלה, ואילו ההגדרה של <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> כרצפה התחתונה מונעת ממנה ליפול מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></span> כך היא נלכדת במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></p>\n<p>לפי הגדרת הגבול באינסוף (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.54\\)</span>),</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = L\\)</span> במובן הסופי. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: קיום האינפימום <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> של קבוצת הערכים.</strong> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A = \\{f(x) \\mid x \\in (a,\\infty)\\}\\)</span>.</span> הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> אינו ריק (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+1 \\in (a,\\infty)\\)</span>),</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A \\ne \\emptyset\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K &gt; 0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)| \\le K\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>,</span> ובפרט <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) \\ge -K\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה מלרע. לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span> (קיום חסם תחתון, הנובע מאקסיומת השלמות — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>),</span> קיים לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסם תחתון ממשי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L := \\inf A \\in \\mathbb{R}\\)</span>.</span></p>","<p><strong>שלב 2: הוכחת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = L\\)</span> לפי הגדרת הגבול באינסוף.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon &gt; 0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(L = \\inf A\\)</span></span> הוא החסם התחתון של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span> גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> ולכן אינו חסם מלרע של <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> (אפיון האינפימום, משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.14\\)</span>).</span> לפיכך קיים איבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> הקטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>,</span></span> כלומר קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(M_0 \\in (a,\\infty)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(M_0) &lt; L + \\varepsilon.\\]</div>\n<p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M_0 &gt; a\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; a\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,\\infty)\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יורדת בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>,</span></span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) \\le f(M_0)\\)</span> (למעשה יורדת ממש נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &lt; f(M_0)\\)</span>).</span> מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> הוא חסם מלרע של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\le f(x)\\)</span>.</span> יחדיו מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L - \\varepsilon &lt; L \\le f(x) \\le f(M_0) &lt; L + \\varepsilon,\\]</div>\n<p>ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x) - L| &lt; \\varepsilon\\)</span>.</span></p>\n<p><em>למה?</em> מרגע <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חצתה למטה את הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L+\\varepsilon\\)</span>,</span> הירידה מונעת ממנה לחזור למעלה, ואילו ההגדרה של <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> כרצפה התחתונה מונעת ממנה ליפול מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></span> כך היא נלכדת במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></p>\n<p>לפי הגדרת הגבול באינסוף (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.54\\)</span>),</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = L\\)</span> במובן הסופי. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לצטט את משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> (&quot;פונקציה מונוטונית וחסימות&quot;) במקום להוכיח — השאלה מבקשת להוכיח את המשפט עצמו עבור גבול באינסוף.</li><li>לא להשתמש בכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>:</span> בלי החסימות, האינפימום אינו קיים (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.11\\)</span> דורש חסם מלרע, לא סתם קבוצה לא ריקה).</li><li>לשכוח לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(M_0 \\in (a,\\infty)\\)</span> ולוודא <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; M_0\\)</span></span> אכן שייך לתחום ההגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>.</span></li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הטענה אינה נכונה — שמו לב שנעלמה הדרישה שהפונקציה <strong>חסומה</strong>! אפשר להישאר שטוחים בהתחלה (לא יורדת ממש) ואחר כך לצנוח למינוס אינסוף.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הטענה אינה נכונה — שמו לב שנעלמה הדרישה שהפונקציה <strong>חסומה</strong>! אפשר להישאר שטוחים בהתחלה (לא יורדת ממש) ואחר כך לצנוח למינוס אינסוף.</p>\n<p><strong>תמונה בראש</strong>: נסו לדמיין מקפצת סקי שבה הקטע הראשון אופקי (הגובה נשאר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> כך שזה יורד במובן החלש אבל לא יורד ממש), ואחרי המטר הראשון המסלול הופך לירידה אינסופית בקו ישר למטה. הגבול בסוף יהיה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>,</span> לא מספר סופי.</p>\n<p><strong>עם מספרים</strong>: עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-x\\)</span></span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1,\\infty)\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_1=0.25\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x_2=0.5\\)</span></span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0.25)=0=f(0.5)\\)</span>,</span> ולכן אינה יורדת ממש, היא יורדת במובן החלש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> ועדיין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(100)=-99 \\to -\\infty\\)</span>.</span></p>\n<p><strong>יורדת במובן החלש</strong> פירושו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) \\ge f(x_2)\\)</span> (מותר להישאר באותו גובה). <strong>יורדת</strong> (בקורס זה: יורדת ממש) פירושו <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &gt; f(x_2)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הגרף הכחול (בדוגמה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span>)</span> שטוח על <span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>,</span> ולכן הוא אינו יורד ממש, אבל החל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הוא יורד בקו ישר <span class=\"math math-inline\" dir=\"ltr\">\\(y=1-x\\)</span> ושואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.3,&quot;xmax&quot;:6,&quot;ymin&quot;:-4.5,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{1-x-|1-x|}{2}+0\\\\cdot\\\\ln(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.25, 0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5, 0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;bend&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איזה תנאי חשוב מסעיף א הושמט כאן","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איזה תנאי חשוב מסעיף א הושמט כאן</p><div class=\"callout-body\"><p>השוו את נוסח סעיף ב לסעיף א: איזו מילה קריטית נעלמה?</p></div></div>"},{"title":"רמז 2: דוגמה פשוטה לכל $a$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמה פשוטה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></p><div class=\"callout-body\"><p>עשו את <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> קבועה בקטע ההתחלתי <span class=\"math math-inline\" dir=\"ltr\">\\((a, a+1]\\)</span> כדי לשבור ירידה ממש, ואז שלחו אותה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-\\infty\\)</span></span> כפונקציה יורדת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a+1,\\infty)\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נבנה פונקציה מפוצלת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span>:</span> קבועה ושווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,a+1]\\)</span>,</span> ושווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(a+1-x\\)</span></span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a+1,\\infty)\\)</span>.</span> נוודא במפורש את שלוש הדרישות: ירידה במובן החלש, אי-היותה יורדת ממש, ושלילת קיום גבול סופי באינסוף (שכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x)=-\\infty\\)</span>).</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: הטענה אינה נכונה.</strong></p>\n<p><strong>שלב 1: בניית דוגמה נגדית.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a \\in \\mathbb{R}\\)</span>,</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f: (a,\\infty) \\to \\mathbb{R}\\)</span> כך:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) = \\begin{cases} 0 &amp; a &lt; x \\le a+1 \\\\ a+1-x &amp; x &gt; a+1. \\end{cases}\\]</div>\n<p><strong>שלב 2: בדיקת התנאים.</strong></p>\n<ol><li><strong>יורדת במובן החלש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span></span></strong>: יהיו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a &lt; x_1 &lt; x_2\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) \\ge f(x_2)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> בקטע.<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 \\le a+1\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 \\ge 0 = f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\le a+1 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 &gt; a+1-x_2 = f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+1 &lt; x_1 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = a+1-x_1 &gt; a+1-x_2 = f(x_2)\\)</span>.</span></li></ul></li></ol>\n<ol start=\"2\"><li><strong>אינה יורדת ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span></span></strong>: נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 = a+\\frac{1}{4}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = a+\\frac{1}{2}\\)</span>.</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a &lt; x_1 &lt; x_2 \\le a+1\\)</span>,</span> אך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 = f(x_2)\\)</span>,</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &gt; f(x_2)\\)</span>.</span></li></ol>\n<p><strong>שלב 3: הפרכת המסקנה.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M \\in \\mathbb{R}\\)</span>,</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(K = \\max\\{a+1, a+1-M\\}\\)</span>.</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; K\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; a+1\\)</span> וכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = a+1-x &lt; M\\)</span>.</span> לפי הגדרת הגבול האינסופי באינסוף, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = -\\infty\\)</span>,</span> ובפרט לא קיים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גבול סופי <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>.</span></span></p>\n<p><em>למה?</em> ההנחה שנעלמה מסעיף א היא החסימות מלרע; בלעדיה גם פונקציה שיורדת בחלקה ונופלת מטה בלי תחתית עומדת בכל שאר התנאים ובורחת למינוס אינסוף.</p>\n<p>לכן הטענה אינה נכונה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>התשובה: הטענה אינה נכונה.</strong></p>\n<p><strong>שלב 1: בניית דוגמה נגדית.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a \\in \\mathbb{R}\\)</span>,</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f: (a,\\infty) \\to \\mathbb{R}\\)</span> כך:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) = \\begin{cases} 0 &amp; a &lt; x \\le a+1 \\\\ a+1-x &amp; x &gt; a+1. \\end{cases}\\]</div>","<p><strong>שלב 2: בדיקת התנאים.</strong></p>\n<ol><li><strong>יורדת במובן החלש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span></span></strong>: יהיו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a &lt; x_1 &lt; x_2\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) \\ge f(x_2)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> בקטע.<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 \\le a+1\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 \\ge 0 = f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\le a+1 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 &gt; a+1-x_2 = f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a+1 &lt; x_1 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = a+1-x_1 &gt; a+1-x_2 = f(x_2)\\)</span>.</span></li></ul></li></ol>\n<ol start=\"2\"><li><strong>אינה יורדת ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,\\infty)\\)</span></span></strong>: נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 = a+\\frac{1}{4}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = a+\\frac{1}{2}\\)</span>.</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a &lt; x_1 &lt; x_2 \\le a+1\\)</span>,</span> אך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) = 0 = f(x_2)\\)</span>,</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &gt; f(x_2)\\)</span>.</span></li></ol>","<p><strong>שלב 3: הפרכת המסקנה.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M \\in \\mathbb{R}\\)</span>,</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(K = \\max\\{a+1, a+1-M\\}\\)</span>.</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; K\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; a+1\\)</span> וכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = a+1-x &lt; M\\)</span>.</span> לפי הגדרת הגבול האינסופי באינסוף, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty} f(x) = -\\infty\\)</span>,</span> ובפרט לא קיים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גבול סופי <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>.</span></span></p>\n<p><em>למה?</em> ההנחה שנעלמה מסעיף א היא החסימות מלרע; בלעדיה גם פונקציה שיורדת בחלקה ונופלת מטה בלי תחתית עומדת בכל שאר התנאים ובורחת למינוס אינסוף.</p>\n<p>לכן הטענה אינה נכונה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לתת דוגמה נגדית רק עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a=0\\)</span> במקום לכל <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in\\mathbb{R}\\)</span> שנתון בשאלה (קל לכתוב באמצעות <span class=\"math math-inline\" dir=\"ltr\">\\(a+1\\)</span> כדי שיתאים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span>).</span></li><li>לשכוח לבדוק את מעבר הגבול בין הענפים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\le a+1 &lt; x_2\\)</span>)</span> בעת הוכחת המונוטוניות החלשה.</li><li>לחשוב ש-&quot;אינה יורדת&quot; פירושו שהיא חייבת לעלות באיזשהו מקום; בניסוח הקורס &quot;יורדת&quot; היא יורדת ממש, ולכן קטע קבוע קצר מספיק כדי שלא תהיה יורדת ממש.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span></span> נק׳) הוכיחו שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x^2 \\arctan x\\)</span> מקבלת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span></span> כל ערך ממשי לכל היותר פעם אחת.</p>\n<p><strong>ב.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(15\\)</span></span> נק׳) הוכיחו שלמשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x = x\\)</span> יש אינסוף פתרונות חיוביים. <strong>הערה</strong>: ידוע שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> שלם, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to(\\frac{1}{2}\\pi+\\pi k)^+}\\tan x = -\\infty\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to(\\frac{1}{2}\\pi+\\pi k)^-}\\tan x = \\infty\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הנגזרת של הפונקציה חיובית בכל נקודה חוץ מאפס (שם היא אפס), ולכן הפונקציה עולה ממש בכל הישר ולעולם אינה חוזרת לאותו גובה פעמיים.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הנגזרת של הפונקציה חיובית בכל נקודה חוץ מאפס (שם היא אפס), ולכן הפונקציה עולה ממש בכל הישר ולעולם אינה חוזרת לאותו גובה פעמיים.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על מעלית שנוסעת תמיד כלפי מעלה — גם אם בקומה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> היא מאטה לשבריר שנייה ועוצרת בשיפוע אפס, מיד אחר כך היא ממשיכה לטפס למעלה. מעלית שרק מטפסת לעולם אינה עוברת באותו גובה פעמיים. שימו לב למה <span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x\\)</span> תמיד חיובי חוץ <span class=\"nobr\">מב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span></span> בצד החיובי גם <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> חיוביים, ובצד השלילי שניהם שליליים (ומכפלת שני שליליים חיובית!).</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=-1\\)</span></span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1)^2\\arctan(-1)=-\\frac{\\pi}{4}\\approx -0.785\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(+\\frac{\\pi}{4}\\approx +0.785\\)</span>.</span> והשיפוע: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=-1\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2(-1)(-\\frac{\\pi}{4})+\\frac{1}{2}=\\frac{\\pi}{2}+\\frac{1}{2}&gt;0\\)</span>,</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הוא גם כן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\frac{1}{2}&gt;0\\)</span>.</span></p>\n<p><strong>מקבלת כל ערך לכל היותר פעם אחת</strong> היא בדיוק התכונה שהפונקציה <strong>חד-חד-ערכית</strong> (אין שתי נקודות שונות <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\ne x_2\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1)=f(x_2)\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הגרף של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\arctan x\\)</span>.</span> הזיזו את הקו הירוק האופקי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=k\\)</span>:</span> לא משנה איזה גובה <span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span> תבחרו, הוא חותך את הגרף הכחול בנקודה אחת בלבד, כי העקומה עולה ממש לכל אורך הישר (ורק בנקודה הכתומה <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> משטחת לרגע).</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2.5,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-3,&quot;ymax&quot;:3}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;k&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;k=0.5&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-2.5,&quot;max&quot;:2.5,&quot;step&quot;:0.25}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x^{2}\\\\arctan(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;yk&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=k&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;o&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0, 0)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: גוזרים ובודקים סימן — משני הצדדים של האפס","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: גוזרים ובודקים סימן — משני הצדדים של האפס</p><div class=\"callout-body\"><p>גזרו את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\arctan x\\)</span> לפי כלל המכפלה. מדוע האיבר <span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x\\)</span> אי-שלילי גם <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: לטפל בנקודה $x=0$ בצורה מסודרת","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: לטפל בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> בצורה מסודרת</p><div class=\"callout-body\"><p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>,</span></span> פצלו לקטעים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span> על קטע פתוח + רציפות בקצה) והסיקו עלייה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגזור את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\arctan x\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span></span> ונראה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) &gt; 0\\)</span> (כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></span> תמיד שווי-סימן). ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span> ומרציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> נסיק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> עולה ממש בקטעים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> ולכן עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> — ומכאן שכל ערך מתקבל לכל היותר פעם אחת.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: גזירה ובדיקת סימן הנגזרת.</strong> נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = x^2\\arctan x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in \\mathbb{R}\\)</span>.</span> הפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></span> גזירות בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28\\)</span>),</span> ולכן לפי כלל המכפלה (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.12\\)</span>)</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (ובפרט רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>,</span> משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>),</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = 2x\\arctan x + \\frac{x^2}{1+x^2}.\\]</div>\n<p>נבדוק את סימן <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span>:</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan t)' = \\frac{1}{1+t^2} &gt; 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan 0 = 0\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> חיובית לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> ושלילית לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 0\\)</span> (למשל ממשפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>).</span></p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span>:</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(2x &gt; 0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x &gt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x &gt; 0\\)</span>.</span></li><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 0\\)</span>:</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(2x &lt; 0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x &lt; 0\\)</span>,</span> ולכן מכפלתם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x &gt; 0\\)</span>.</span></li></ul>\n<p>בנוסף, <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x^2}{1+x^2} &gt; 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) &gt; 0.\\]</div>\n<p><em>למה?</em> משני הצדדים של האפס <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></span> הם בעלי אותו סימן, אז המכפלה שלהם חיובית בדיוק כמו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\cdot x\\)</span></span> חיובי. רק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הנגזרת מתאפסת לרגע.</p>\n<p><strong>שלב 2: עלייה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> וחד-חד-ערכיות.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטעים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) &gt; 0\\)</span> בקטעים הפתוחים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span> לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <strong>עולה ממש</strong> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> וכן עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>:</span></span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 \\le 0\\)</span>,</span> שניהם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\ge 0\\)</span>,</span> שניהם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; 0 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(0) &lt; f(x_2)\\)</span>.</span></li></ul>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> עולה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span> לכן לכל שני מספרים שונים <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\ne x_2\\)</span> (בהנחה <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> בהגבלת סימון) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) \\ne f(x_2)\\)</span>.</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת כל ערך ממשי לכל היותר פעם אחת. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: גזירה ובדיקת סימן הנגזרת.</strong> נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = x^2\\arctan x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in \\mathbb{R}\\)</span>.</span> הפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></span> גזירות בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28\\)</span>),</span> ולכן לפי כלל המכפלה (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.12\\)</span>)</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (ובפרט רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>,</span> משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>),</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) = 2x\\arctan x + \\frac{x^2}{1+x^2}.\\]</div>\n<p>נבדוק את סימן <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span>:</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((\\arctan t)' = \\frac{1}{1+t^2} &gt; 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan 0 = 0\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> חיובית לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> ושלילית לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 0\\)</span> (למשל ממשפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>).</span></p>\n<ul><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span>:</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(2x &gt; 0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x &gt; 0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x &gt; 0\\)</span>.</span></li><li>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &lt; 0\\)</span>:</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(2x &lt; 0\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x &lt; 0\\)</span>,</span> ולכן מכפלתם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x &gt; 0\\)</span>.</span></li></ul>\n<p>בנוסף, <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{x^2}{1+x^2} &gt; 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x) &gt; 0.\\]</div>\n<p><em>למה?</em> משני הצדדים של האפס <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span></span> הם בעלי אותו סימן, אז המכפלה שלהם חיובית בדיוק כמו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\cdot x\\)</span></span> חיובי. רק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הנגזרת מתאפסת לרגע.</p>","<p><strong>שלב 2: עלייה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> וחד-חד-ערכיות.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטעים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) &gt; 0\\)</span> בקטעים הפתוחים <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span> לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <strong>עולה ממש</strong> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span> וכן עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>:</span></span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 \\le 0\\)</span>,</span> שניהם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((-\\infty,0]\\)</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\ge 0\\)</span>,</span> שניהם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; 0 &lt; x_2\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(0) &lt; f(x_2)\\)</span>.</span></li></ul>\n<p>מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> עולה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span> לכן לכל שני מספרים שונים <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 \\ne x_2\\)</span> (בהנחה <span class=\"math math-inline\" dir=\"ltr\">\\(x_1 &lt; x_2\\)</span> בהגבלת סימון) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) &lt; f(x_2)\\)</span>,</span> ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1) \\ne f(x_2)\\)</span>.</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת כל ערך ממשי לכל היותר פעם אחת. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לטעון ש-&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x) &gt; 0\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb{R}\\)</span>&quot; — לא נכון! <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span></li><li>להשתמש במשפט רול <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8.5\\)</span>)</span> בצורה פזיזה: אם מניחים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1)=f(x_2)\\)</span> ומקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x_1,x_2)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>,</span> זה נותן <span class=\"math math-inline\" dir=\"ltr\">\\(c=0\\)</span> — וזה עדיין לא שולל שתי נקודות משני הצדדים של <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בלי נימוק נוסף (כמו המונוטוניות בכל ענף או בדיקת הסימן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_1)&lt;0&lt;f(x_2)\\)</span>).</span></li><li>לחשוב <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2x\\arctan x &lt; 0\\)</span>:</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> שלילי, גם <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> שלילי והמכפלה חיובית.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כל ענף של <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x\\)</span> מטפס עד אינסוף לפני האסימפטוטה שלו, ולכן בכל ענף חיובי הוא חייב לחתוך את הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כל ענף של <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x\\)</span> מטפס עד אינסוף לפני האסימפטוטה שלו, ולכן בכל ענף חיובי הוא חייב לחתוך את הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: דמיינו את הקו האלכסוני <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> שחוצה את ציר <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> והולך למעלה במתינות. פונקציית הטנגנס בנויה מענפים חוזרים ונשנים: כל קטע <span class=\"math math-inline\" dir=\"ltr\">\\([\\pi k, \\frac{\\pi}{2}+\\pi k)\\)</span> מתחיל בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> (מתחת לישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>)</span> וטס אל מעל לכל גובה שבעולם <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span>)</span> לקראת הקיר האנכי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\pi k\\)</span>.</span> מסלול רציף שמתחיל מתחת לישר וטס מעליו מוכרח לחצות את הישר בכל קטע כזה — ויש אינסוף קטעים כאלה!</p>\n<p><strong>עם מספרים</strong>: בקטע הראשון <span class=\"math math-inline\" dir=\"ltr\">\\([ \\pi, 1.5\\pi )\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k=1\\)</span>):</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=\\pi \\approx 3.14\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan\\pi = 0 &lt; 3.14\\)</span>;</span> קרוב לקיר הימני, <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=4.6\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan(4.6)\\approx 8.86 &gt; 4.6\\)</span>.</span> לכן ביניהם יש פתרון (בסביבות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\approx 4.493\\)</span>).</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([2\\pi, 2.5\\pi)\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k=2\\)</span>)</span> יש עוד פתרון (בסביבות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.725\\)</span>),</span> וכן הלאה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb{N}\\)</span>.</span></p>\n<p><strong>משפט ערך הביניים</strong> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.29\\)</span>)</span> דורש פונקציה <strong>רציפה</strong> על <strong>קטע סגור</strong> <span class=\"math math-inline\" dir=\"ltr\">\\([a_k, b_k]\\)</span> עם סימנים מנוגדים בקצוות — לכן ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(b_k\\)</span> קצת משמאל לאסימפטוטה במקום את האסימפטוטה עצמה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול ענפי <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x\\)</span> ובאדום הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span> הקווים האפורים המקווקווים הם האסימפטוטות <span class=\"math math-inline\" dir=\"ltr\">\\(x=1.5\\pi\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=2.5\\pi\\)</span>.</span></span> בכל ענף מימין לציר יש נקודת חיתוך ירוקה: הראשונה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((4.493, 4.493)\\)</span></span> והשנייה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((7.725, 7.725)\\)</span>,</span></span> וכך ממשיכות להתקבל אינסוף נקודות חיתוך.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.5,&quot;xmax&quot;:10,&quot;ymin&quot;:-2,&quot;ymax&quot;:10}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\tan(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;id&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;a1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1.5\\\\pi&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;a2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2.5\\\\pi&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;s1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(4.493, 4.493)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;s2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(7.725, 7.725)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: לבודד ענפים חיוביים זרים זה לזה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: לבודד ענפים חיוביים זרים זה לזה</p><div class=\"callout-body\"><p>הגדירו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=\\tan x - x\\)</span>.</span> הסתכלו על הקטעים <span class=\"math math-inline\" dir=\"ltr\">\\(\\left[\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span>).</span> מה סימן <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> בקצה השמאלי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi k\\)</span>?</span></p></div></div>"},{"title":"רמז 2: להפוך גבול אינסופי לנקודה סופית $b_k$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: להפוך גבול אינסופי לנקודה סופית <span class=\"math math-inline\" dir=\"ltr\">\\(b_k\\)</span></p><div class=\"callout-body\"><p>מהגבול הנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to(\\frac{1}{2}\\pi+\\pi k)^-}\\tan x = \\infty\\)</span>,</span> הסבירו מדוע קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(b_k \\in \\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(b_k) &gt; 0\\)</span>,</span> והפעילו את משפט ערך הביניים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(5.29\\)</span>)</span> על הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([\\pi k, b_k]\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=\\tan x - x\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> נבדוק את <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left[\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה שם, שלילית בקצה השמאלי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(h(\\pi k)=-\\pi k&lt;0\\)</span>),</span> ושואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span> בגבול משמאל לקצה הימני (לפי הערת השאלה <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim x = \\frac{\\pi}{2}+\\pi k\\)</span>).</span></span> לכן קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(b_k\\)</span> בקטע שבה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(b_k)&gt;0\\)</span>.</span> ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.29\\)</span> על <span class=\"math math-inline\" dir=\"ltr\">\\([\\pi k, b_k]\\)</span> נקבל פתרון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_k \\in (\\pi k, \\frac{\\pi}{2}+\\pi k)\\)</span>,</span> וכל הפתרונות הללו חיוביים ושונים זה מזה.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הגדרת פונקציית ההפרש ובחירת קטעים זרים.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = \\tan x - x\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בתחום ההגדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x\\)</span>.</span> פתרונות המשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x = x\\)</span> הם בדיוק האפסים של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>.</span></p>\n<p>יהי <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span>).</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left[\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x \\ne 0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x = \\frac{\\sin x}{\\cos x}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\)</span></span> רציפות שם (משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(5.11\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.18\\)</span>).</span></span></p>\n<p><strong>שלב 2: מציאת שני קצוות עם סימנים מנוגדים.</strong> בקצה השמאלי <span class=\"math math-inline\" dir=\"ltr\">\\(a_k := \\pi k &gt; 0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(a_k) = \\tan(\\pi k) - \\pi k = 0 - \\pi k = -\\pi k &lt; 0.\\]</div>\n<p>כעת נתבונן בגבול משמאל <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\pi k\\)</span>:</span></span> לפי ההערה בשאלה, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} \\tan x = +\\infty\\)</span>,</span> ואילו <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} (-x) = -\\left(\\frac{\\pi}{2}+\\pi k\\right)\\)</span> (גבול סופי). לפי אריתמטיקה של גבולות במובן הרחב (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.53\\)</span>),</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} h(x) = \\infty.\\]</div>\n<p>לפי הגדרת הגבול האינסופי משמאל (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=0\\)</span>),</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_k &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in \\left(\\frac{\\pi}{2}+\\pi k - \\delta_k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> (שגם גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi k\\)</span>)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x) &gt; 0\\)</span>.</span> נבחר נקודה אחת כזו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_k \\in \\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_k &gt; a_k\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(b_k) &gt; 0\\)</span>.</span></span></p>\n<p><em>למה?</em> אנחנו לא יכולים להציב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\pi k\\)</span> בפונקציה עצמה כי הטנגנס מתפוצץ שם, אבל השאיפה לאינסוף מבטיחה שמספיק קרוב אליה הגרף כבר נמצא גבוה מעל ציר <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> — ואז אפשר לחתוך את הקטע בקיר סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_k\\)</span>.</span></p>\n<p><strong>שלב 3: הפעלת משפט ערך הביניים.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a_k, b_k]\\)</span>,</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(a_k) &lt; 0 &lt; h(b_k)\\)</span>.</span> לפי משפט ערך הביניים (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.29\\)</span>),</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c_k \\in (a_k, b_k) \\subset \\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(c_k) = 0\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan c_k = c_k\\)</span>.</span></p>\n<p><strong>שלב 4: אינסוף פתרונות חיוביים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_k &gt; \\pi k \\ge \\pi &gt; 0\\)</span>,</span> ולכן כל <span class=\"math math-inline\" dir=\"ltr\">\\(c_k\\)</span> הוא פתרון חיובי. יתר על כן, הקטעים <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(k=1,2,3,\\dots\\)</span> זרים זה לזה (שכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi k &lt; c_k &lt; \\frac{\\pi}{2}+\\pi k &lt; \\pi(k+1) &lt; c_{k+1}\\)</span>),</span> ולכן כל הפתרונות <span class=\"math math-inline\" dir=\"ltr\">\\(c_1 &lt; c_2 &lt; c_3 &lt; \\dots\\)</span> שונים זה מזה. מכאן שיש למשוואה אינסוף פתרונות חיוביים. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: הגדרת פונקציית ההפרש ובחירת קטעים זרים.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = \\tan x - x\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בתחום ההגדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x\\)</span>.</span> פתרונות המשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x = x\\)</span> הם בדיוק האפסים של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span>.</span></p>\n<p>יהי <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span>).</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left[\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x \\ne 0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\tan x = \\frac{\\sin x}{\\cos x}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\)</span></span> רציפות שם (משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(5.11\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.18\\)</span>).</span></span></p>","<p><strong>שלב 2: מציאת שני קצוות עם סימנים מנוגדים.</strong> בקצה השמאלי <span class=\"math math-inline\" dir=\"ltr\">\\(a_k := \\pi k &gt; 0\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(a_k) = \\tan(\\pi k) - \\pi k = 0 - \\pi k = -\\pi k &lt; 0.\\]</div>\n<p>כעת נתבונן בגבול משמאל <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\pi k\\)</span>:</span></span> לפי ההערה בשאלה, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} \\tan x = +\\infty\\)</span>,</span> ואילו <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} (-x) = -\\left(\\frac{\\pi}{2}+\\pi k\\right)\\)</span> (גבול סופי). לפי אריתמטיקה של גבולות במובן הרחב (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.53\\)</span>),</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to (\\frac{1}{2}\\pi+\\pi k)^-} h(x) = \\infty.\\]</div>\n<p>לפי הגדרת הגבול האינסופי משמאל (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=0\\)</span>),</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_k &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in \\left(\\frac{\\pi}{2}+\\pi k - \\delta_k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> (שגם גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi k\\)</span>)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x) &gt; 0\\)</span>.</span> נבחר נקודה אחת כזו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_k \\in \\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_k &gt; a_k\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(b_k) &gt; 0\\)</span>.</span></span></p>\n<p><em>למה?</em> אנחנו לא יכולים להציב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}+\\pi k\\)</span> בפונקציה עצמה כי הטנגנס מתפוצץ שם, אבל השאיפה לאינסוף מבטיחה שמספיק קרוב אליה הגרף כבר נמצא גבוה מעל ציר <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> — ואז אפשר לחתוך את הקטע בקיר סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_k\\)</span>.</span></p>","<p><strong>שלב 3: הפעלת משפט ערך הביניים.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> רציפה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a_k, b_k]\\)</span>,</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(a_k) &lt; 0 &lt; h(b_k)\\)</span>.</span> לפי משפט ערך הביניים (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.29\\)</span>),</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c_k \\in (a_k, b_k) \\subset \\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(c_k) = 0\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\tan c_k = c_k\\)</span>.</span></p>","<p><strong>שלב 4: אינסוף פתרונות חיוביים.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_k &gt; \\pi k \\ge \\pi &gt; 0\\)</span>,</span> ולכן כל <span class=\"math math-inline\" dir=\"ltr\">\\(c_k\\)</span> הוא פתרון חיובי. יתר על כן, הקטעים <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\pi k, \\frac{\\pi}{2}+\\pi k\\right)\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(k=1,2,3,\\dots\\)</span> זרים זה לזה (שכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pi k &lt; c_k &lt; \\frac{\\pi}{2}+\\pi k &lt; \\pi(k+1) &lt; c_{k+1}\\)</span>),</span> ולכן כל הפתרונות <span class=\"math math-inline\" dir=\"ltr\">\\(c_1 &lt; c_2 &lt; c_3 &lt; \\dots\\)</span> שונים זה מזה. מכאן שיש למשוואה אינסוף פתרונות חיוביים. <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לנסות להציב &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(h(\\frac{\\pi}{2}+\\pi k) = \\infty\\)</span>&quot; ולהפעיל את משפט ערך הביניים על הקטע החצי-פתוח <span class=\"math math-inline\" dir=\"ltr\">\\([\\pi k, \\frac{\\pi}{2}+\\pi k)\\)</span> — אסור! המשפט דורש קטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a_k, b_k]\\)</span> וערכים ממשיים סופיים בשני הקצוות.</li><li>לא לנמק מדוע הפתרונות שמצאנו חיוביים ושונים זה מזה (עבור <span class=\"math math-inline\" dir=\"ltr\">\\(k=0\\)</span> עלולים לקבל רק את <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> שאינו חיובי!).</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/40/q2\">2026א · מועד 83, שאלה 2</a></p>","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x &lt; x\\)</span>.</span></p>\n<p><span class=\"math math-inline\" dir=\"ltr\">\\((2)\\)</span> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> סדרה הנתונה ע״י: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = \\sin(\\arctan x_n),\\ 0 &lt; x_1 &lt; \\frac{\\pi}{2}\\)</span>.</span> הוכיחו כי <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וחשבו את גבולה. <strong>הדרכה</strong>: מותר להשתמש באי השוויון הידוע: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x \\le x\\)</span>.</span> <strong>הערה</strong>: מותר לכם להשתמש בטענת סעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> גם אם לא הוכחתם אותה.</p></div></div>","parts":[{"label":"(1)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">שני הגרפים יוצאים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>,</span></span> אבל השיפוע של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> מפגר אחרי הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: שני הגרפים יוצאים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>,</span></span> אבל השיפוע של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> מפגר אחרי הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: שני מטיילים מתחילים בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ברגע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span> המטייל על הישר <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> מטפס בקצב קבוע של מטר לגובה לכל מטר הצידה (שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span> המטייל על <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span> מטפס לאט יותר (שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1+x^2}&lt;1\\)</span>),</span> ולכן בכל רגע אחרי הזינוק הוא נמוך יותר.</p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan 1 = \\frac{\\pi}{4} \\approx 0.785 &lt; 1\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\sqrt{3}\\approx 1.732\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan(\\sqrt{3}) = \\frac{\\pi}{3} \\approx 1.047 &lt; 1.732\\)</span>.</span></p>\n<p><strong>אי-שוויון מנגזרת</strong>: אם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> יש שוויון ובהמשך הנגזרת של הפרש הפונקציות חיובית ממש, הפונקציה הגדולה משיגה פער חיובי הולך וגדל.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>באדום הקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> (שיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span> ובכחול העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\arctan x\\)</span> שיוצאת מאותה ראשית <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> אך מתעקלת מתחת לישר האדום לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> בירוק ההפרש החיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x-\\arctan x\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:3.5,&quot;ymin&quot;:-0.2,&quot;ymax&quot;:3.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;id&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;at&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\arctan(x)+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;df&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x-\\\\arctan(x)+0\\\\cdot\\\\sqrt{x}&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 0.7854)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: פונקציית הפרש ונגזרתה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: פונקציית הפרש ונגזרתה</p><div class=\"callout-body\"><p>הגדירו <span class=\"math math-inline\" dir=\"ltr\">\\(g(t)=t-\\arctan t\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>.</span></span> מהו <span class=\"math math-inline\" dir=\"ltr\">\\(g(0)\\)</span> ומהו סימן הנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(t)\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: שימוש במשפט לגראנז׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש במשפט לגראנז׳</p><div class=\"callout-body\"><p>הפעילו את משפט לגראנז׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8.6\\)</span>)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(t)=t-\\arctan t\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> נבדוק רציפות וגזירות, ונראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(t)=\\frac{t^2}{1+t^2}&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;0\\)</span>.</span> לפי משפט לגראנז׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8.6\\)</span>)</span> על <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> יחד עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0)=0\\)</span>,</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span>.</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(t) = t - \\arctan t\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0, x]\\)</span>.</span></p>\n<p><strong>שלב 1: תנאי משפט לגראנז׳ והנגזרת.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan t\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28\\)</span>),</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> ובפרט רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>)</span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(t \\in (0, x)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(t) = 1 - \\frac{1}{1+t^2} = \\frac{t^2}{1+t^2} &gt; 0.\\]</div>\n<p><strong>שלב 2: משפט לגראנז׳.</strong> לפי משפט לגראנז׳ (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.6\\)</span>)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c \\in (0,x)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) - g(0) = g'(c)(x - 0).\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0) = 0 - \\arctan 0 = 0\\)</span>,</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(c) = \\frac{c^2}{1+c^2} &gt; 0\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) = g'(c)x &gt; 0 \\implies x - \\arctan x &gt; 0 \\implies \\arctan x &lt; x. \\quad \\blacksquare\\]</div>\n<p><em>למה?</em> משמעות הנגזרת החיובית היא שהמרחק <span class=\"math math-inline\" dir=\"ltr\">\\(t-\\arctan t\\)</span> גדל בכל צעד ימינה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ומכיוון שבאפס הוא היה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> הוא חיובי ממש.</p></div></div>","steps":["<p>יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span>.</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(t) = t - \\arctan t\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0, x]\\)</span>.</span></p>\n<p><strong>שלב 1: תנאי משפט לגראנז׳ והנגזרת.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan t\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28\\)</span>),</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> ובפרט רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>)</span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(t \\in (0, x)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(t) = 1 - \\frac{1}{1+t^2} = \\frac{t^2}{1+t^2} &gt; 0.\\]</div>","<p><strong>שלב 2: משפט לגראנז׳.</strong> לפי משפט לגראנז׳ (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.6\\)</span>)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c \\in (0,x)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) - g(0) = g'(c)(x - 0).\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0) = 0 - \\arctan 0 = 0\\)</span>,</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(x &gt; 0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(c) = \\frac{c^2}{1+c^2} &gt; 0\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) = g'(c)x &gt; 0 \\implies x - \\arctan x &gt; 0 \\implies \\arctan x &lt; x. \\quad \\blacksquare\\]</div>\n<p><em>למה?</em> משמעות הנגזרת החיובית היא שהמרחק <span class=\"math math-inline\" dir=\"ltr\">\\(t-\\arctan t\\)</span> גדל בכל צעד ימינה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ומכיוון שבאפס הוא היה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> הוא חיובי ממש.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח לחשב את ערך ההתחלה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0)=0\\)</span>:</span> בלי <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0)\\ge 0\\)</span>,</span></span> נגזרת חיובית לבדה לא מוכיחה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;0\\)</span>.</span></li><li>לגזור רק ולהסתפק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span></span> בלי לקשר <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(g(0)=0\\)</span></span> דרך לגראנז׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8.6\\)</span>)</span> או משפט המונוטוניות <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>).</span></li></ul></div></div>"},{"label":"(2)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כל איבר שומר על הסדרה חיובית ונמוכה מהאיבר הקודם, ולכן הסדרה מתכנסת — ומשני אי-השוויונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span>)</span></span> נובע שהגבול יכול להיות רק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כל איבר שומר על הסדרה חיובית ונמוכה מהאיבר הקודם, ולכן הסדרה מתכנסת — ומשני אי-השוויונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span>)</span></span> נובע שהגבול יכול להיות רק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: נחשוב על הסדרה כתרגיל חזרתי בשני שלבים: מכניסים מספר חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span>,</span></span> שמקטינה אותו (לפי סעיף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span> ואז מכניסים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span>,</span></span> שמשאירה אותו חיובי וגם מקטינה (או לא מגדילה) אותו עוד קצת! כך המספרים מתכווצים בכל צעד לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> בלי לרדת אף פעם מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> אם הסדרה נעצרת בגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span>,</span> היא הייתה צריכה להישאר במקום בנקודת השבת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\sin(\\arctan L)\\)</span>,</span> אבל הראה שנקודה חיובית תמיד יורדת — ולכן הגבול מוכרח להיות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: נתחיל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1 = 1 \\in (0, \\frac{\\pi}{2})\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(\\arctan x)=\\frac{x}{\\sqrt{1+x^2}}\\)</span>,</span></span> נקבל: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = \\frac{1}{\\sqrt{2}} \\approx 0.7071\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_3 = \\frac{1}{\\sqrt{3}} \\approx 0.5774\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_4 = \\frac{1}{\\sqrt{4}} = 0.5\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_5 = \\frac{1}{\\sqrt{5}} \\approx 0.4472\\)</span>,</span> שהולכים בבירור <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>מונוטוניות וחסימות באינדוקציה</strong> מוכיחות יחד <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span></span> יורדת ונשארת מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ואז משפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.16\\)</span> מבטיח גבול.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\sin(\\arctan x)\\)</span> ובאדום הישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> העקומה הכחולה נמצאת מתחת לאלכסון האדום, ונפגשות רק בראשית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span> בדוגמה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1\\)</span>,</span> הצעדים <span class=\"math math-inline\" dir=\"ltr\">\\((n, x_n)\\)</span> (נראים לאורך האלכסון ובגרף <span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}=\\sin(\\arctan x_n)\\)</span> בנקודות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_1=1, x_2\\approx 0.707, x_3\\approx 0.577, x_4=0.5\\)</span>)</span> גולשים מטה לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.3,&quot;ymin&quot;:-0.1,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;h&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;h(x)=\\\\sin(\\\\arctan(x))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;id&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 0.7071)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.7071, 0.5774)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5774, 0.5)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5, 0.4472)&quot;,&quot;color&quot;:&quot;#388c46&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0, 0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: להראות באינדוקציה $0 < x_{n+1} < x_n < \\frac{\\pi}{2}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: להראות באינדוקציה <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n &lt; \\frac{\\pi}{2}\\)</span></p><div class=\"callout-body\"><p>כדי להפעיל את ההדרכה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t \\le t\\)</span></span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;0\\)</span>)</span></span> ואת סעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x_n &lt; x_n\\)</span></span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n&gt;0\\)</span>),</span></span> יש לוודא תחילה באינדוקציה שכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> חיובי ונשאר בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{\\pi}{2})\\)</span>.</span></p></div></div>"},{"title":"רמז 2: מעבר לגבול ושלילת $L>0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מעבר לגבול ושלילת <span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span></p><div class=\"callout-body\"><p>אחרי שמשפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.16\\)</span> נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n \\to L \\ge 0\\)</span>,</span> העבירו גבול בנוסחת הנסיגה בעזרת הרציפות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\circ\\arctan\\)</span>,</span> והשתמשו שוב בסעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> ובהדרכה אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span>!</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח באינדוקציה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb{N}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n &lt; \\frac{\\pi}{2}\\)</span>,</span> בעזרת חיוביות <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{\\pi}{2})\\)</span>,</span> ההדרכה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t\\le t\\)</span>)</span> וסעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x_n &lt; x_n\\)</span>).</span> ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(3.16\\)</span> נסיק קיום גבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\in [0,\\frac{\\pi}{2}]\\)</span>.</span> מרציפות <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(\\arctan x)\\)</span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.15\\)</span>)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\sin(\\arctan L)\\)</span>,</span> ונשלול <span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span> כי אז היה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\sin(\\arctan L)\\le\\arctan L &lt; L\\)</span>,</span> סתירה. מכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הוכחה באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span></span> חיובית, חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{\\pi}{2})\\)</span></span> ויורדת ממש.</strong> נוכיח באינדוקציה על <span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span> שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_n &lt; \\frac{\\pi}{2}\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} &lt; x_n\\)</span>.</span> <em>בדיקת המנה הראשונה / כניסה</em>:</p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_1 &lt; \\frac{\\pi}{2}\\)</span>.</span> מהמונוטוניות של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> (או <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0=\\arctan 0 &lt; \\arctan x_1\\)</span>)</span></span> ומסעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> נקבל:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[0 &lt; \\arctan x_1 &lt; x_1 &lt; \\frac{\\pi}{2}.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t \\in (0,\\frac{\\pi}{2})\\)</span>,</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = \\sin(\\arctan x_1) &gt; 0\\)</span>.</span> מצד שני, לפי ההדרכה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t \\le t\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;0\\)</span>)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t = \\arctan x_1 &gt; 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_2 = \\sin(\\arctan x_1) \\le \\arctan x_1 &lt; x_1 &lt; \\frac{\\pi}{2}.\\]</div>\n<ul><li><strong>צעד האינדוקציה</strong>: נניח שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_n &lt; \\frac{\\pi}{2}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n\\)</span></span> (בפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; \\frac{\\pi}{2}\\)</span>).</span> באותו אופן עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}\\)</span>:</span></li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[0 &lt; \\arctan x_{n+1} &lt; x_{n+1} &lt; \\frac{\\pi}{2},\\]</div>\n<p>ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+2} = \\sin(\\arctan x_{n+1}) &gt; 0\\)</span>,</span> וכן מהדרכת השאלה וסעיף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_{n+2} = \\sin(\\arctan x_{n+1}) \\le \\arctan x_{n+1} &lt; x_{n+1} &lt; \\frac{\\pi}{2}.\\]</div>\n<p>לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n &lt; \\frac{\\pi}{2}\\)</span>.</span></p>\n<p><em>למה?</em> כל הפעלה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span> על מספר שבין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}\\)</span></span> מקטינה אותו אבל אף פעם לא מורידה אותו עד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> או מתחתיו, ולכן אפשר להמשיך באותו תנאי לנצח.</p>\n<p><strong>שלב 2: קיום הגבול.</strong> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> יורדת ממש וחסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> לפי משפט ההתכנסות המונוטונית (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.16\\)</span>),</span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L := \\lim_{n\\to\\infty} x_n\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> שמירת סדר חלש בגבול (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.31\\)</span>)</span> נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\ge 0\\)</span>.</span></p>\n<p><strong>שלב 3: חישוב הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = \\sin(\\arctan x)\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> כהרכבה של שתי פונקציות רציפות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.15\\)</span>).</span> מכיוון שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n+1})\\)</span> היא הסטה באינדקס של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span>,</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_{n+1} = L\\)</span> (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span> מאפיון היינה לרציפות (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.4\\)</span>)</span> במעבר לגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = \\sin(\\arctan x_n)\\)</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = \\lim_{n\\to\\infty} x_{n+1} = \\lim_{n\\to\\infty} \\sin(\\arctan x_n) = \\sin(\\arctan L).\\]</div>\n<p>נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L &gt; 0\\)</span>.</span> אזי לפי סעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; \\arctan L &lt; L\\)</span>,</span> ולפי ההדרכה (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t=\\arctan L &gt; 0\\)</span>)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(\\arctan L) \\le \\arctan L\\)</span>.</span> בשילוב נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = \\sin(\\arctan L) \\le \\arctan L &lt; L,\\]</div>\n<p>וזו סתירה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(L &lt; L\\)</span>).</span> מכיוון שכבר ידוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\ge 0\\)</span>,</span> מתחייב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L = 0\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_n = 0\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: הוכחה באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span></span> חיובית, חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{\\pi}{2})\\)</span></span> ויורדת ממש.</strong> נוכיח באינדוקציה על <span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span> שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_n &lt; \\frac{\\pi}{2}\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} &lt; x_n\\)</span>.</span> <em>בדיקת המנה הראשונה / כניסה</em>:</p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_1 &lt; \\frac{\\pi}{2}\\)</span>.</span> מהמונוטוניות של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> (או <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0=\\arctan 0 &lt; \\arctan x_1\\)</span>)</span></span> ומסעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> נקבל:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[0 &lt; \\arctan x_1 &lt; x_1 &lt; \\frac{\\pi}{2}.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t \\in (0,\\frac{\\pi}{2})\\)</span>,</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_2 = \\sin(\\arctan x_1) &gt; 0\\)</span>.</span> מצד שני, לפי ההדרכה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin t \\le t\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t&gt;0\\)</span>)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t = \\arctan x_1 &gt; 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_2 = \\sin(\\arctan x_1) \\le \\arctan x_1 &lt; x_1 &lt; \\frac{\\pi}{2}.\\]</div>\n<ul><li><strong>צעד האינדוקציה</strong>: נניח שעבור <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_n &lt; \\frac{\\pi}{2}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n\\)</span></span> (בפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; \\frac{\\pi}{2}\\)</span>).</span> באותו אופן עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1}\\)</span>:</span></li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[0 &lt; \\arctan x_{n+1} &lt; x_{n+1} &lt; \\frac{\\pi}{2},\\]</div>\n<p>ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+2} = \\sin(\\arctan x_{n+1}) &gt; 0\\)</span>,</span> וכן מהדרכת השאלה וסעיף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x_{n+2} = \\sin(\\arctan x_{n+1}) \\le \\arctan x_{n+1} &lt; x_{n+1} &lt; \\frac{\\pi}{2}.\\]</div>\n<p>לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; x_{n+1} &lt; x_n &lt; \\frac{\\pi}{2}\\)</span>.</span></p>\n<p><em>למה?</em> כל הפעלה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan\\)</span> ושל <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\)</span> על מספר שבין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}\\)</span></span> מקטינה אותו אבל אף פעם לא מורידה אותו עד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> או מתחתיו, ולכן אפשר להמשיך באותו תנאי לנצח.</p>","<p><strong>שלב 2: קיום הגבול.</strong> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> יורדת ממש וחסומה מלרע על ידי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> לפי משפט ההתכנסות המונוטונית (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.16\\)</span>),</span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L := \\lim_{n\\to\\infty} x_n\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> שמירת סדר חלש בגבול (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.31\\)</span>)</span> נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\ge 0\\)</span>.</span></p>","<p><strong>שלב 3: חישוב הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = \\sin(\\arctan x)\\)</span> רציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span> כהרכבה של שתי פונקציות רציפות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.15\\)</span>).</span> מכיוון שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n+1})\\)</span> היא הסטה באינדקס של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span>,</span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_{n+1} = L\\)</span> (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span> מאפיון היינה לרציפות (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.4\\)</span>)</span> במעבר לגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = \\sin(\\arctan x_n)\\)</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = \\lim_{n\\to\\infty} x_{n+1} = \\lim_{n\\to\\infty} \\sin(\\arctan x_n) = \\sin(\\arctan L).\\]</div>\n<p>נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L &gt; 0\\)</span>.</span> אזי לפי סעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; \\arctan L &lt; L\\)</span>,</span> ולפי ההדרכה (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t=\\arctan L &gt; 0\\)</span>)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(\\arctan L) \\le \\arctan L\\)</span>.</span> בשילוב נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L = \\sin(\\arctan L) \\le \\arctan L &lt; L,\\]</div>\n<p>וזו סתירה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(L &lt; L\\)</span>).</span> מכיוון שכבר ידוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L \\ge 0\\)</span>,</span> מתחייב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L = 0\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> מתכנסת וגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} x_n = 0\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לטעון &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n+1} = \\sin(\\arctan x_n) \\le \\arctan x_n &lt; x_n\\)</span>&quot; בלי לבדוק תחילה באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_n &gt; 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x_n &gt; 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>:</span> שני אי-השוויונים תקפים רק עבור קלט <strong>חיובי</strong>!</li><li>לקפוץ ישר לפתרון המשוואה <span class=\"math math-inline\" dir=\"ltr\">\\(L = \\sin(\\arctan L)\\)</span> לפני שמוכיחים בכלל שהגבול <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> קיים.</li><li>לחשוב ש-&quot;מונוטונית יורדת וחסומה מלרע <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span>&quot; אומר אוטומטית שהגבול הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> — המשפט מבטיח שגבול <strong>כלשהו</strong> <span class=\"math math-inline\" dir=\"ltr\">\\(L\\ge 0\\)</span> קיים, ואת השוויון <span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span> חייבים להוכיח בנפרד.</li></ul></div></div>"}],"similar":"","mc":null},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p><strong>א.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span></span> נק׳) הוכיחו או הפריכו: תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\(f, g\\)</span> פונקציות המוגדרות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span></span> ומקיימות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)g(x) = 1\\)</span>.</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חיובית <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span></span> אז קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda &gt; 0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x) &gt; \\frac{1}{2f(x)}\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in N^*_\\lambda(0)\\)</span>.</span></p>\n<p><strong>ב.</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(15\\)</span></span> נק׳) <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה המתכנסת לגבול חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span> הוכיחו כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{a_n} = 1\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\((2)\\)</span> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(p(x) = b_T x^T + b_{T-1} x^{T-1} + \\dots + b_1 x + b_0\\)</span> פולינום ממעלה <span class=\"math math-inline\" dir=\"ltr\">\\(T\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T &gt; 0\\)</span>.</span></span> חשבו את הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} \\sqrt[n]{p(n)}\\)</span>.</span> שימו לב: הפולינום <span class=\"math math-inline\" dir=\"ltr\">\\(p(x)\\)</span> הוא פונקציה, אך <span class=\"math math-inline\" dir=\"ltr\">\\(p(n)\\)</span> היא סדרה. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = b_T n^T + b_{T-1} n^{T-1} + \\dots + b_1 n + b_0\\)</span>.</span> הגבול המבוקש <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{p(n)}\\)</span> זהו גבול של סדרה. <strong>הערה</strong>: מותר לכם להשתמש בטענת סעיף <span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> גם אם לא הוכחתם אותה.</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הטענה נכונה — אם המכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)\\)</span> מתקרבת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> אז קרוב מספיק לאפס היא גדולה מחצי, ואפשר לחלק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> החיובית.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הטענה נכונה — אם המכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)\\)</span> מתקרבת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> אז קרוב מספיק לאפס היא גדולה מחצי, ואפשר לחלק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> החיובית.</p>\n<p><strong>תמונה בראש</strong>: נניח שהגובה של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> כפול הגובה של <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מתקרב למספר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> זה אומר שאם נתקרב מספיק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (בתוך חלון קטן מספיק <span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\lambda(0)\\)</span> שבתוך החלון המקורי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span>),</span> המכפלה תהיה קרובה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> עד כדי חצי — כלומר בודאות גדולה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span>.</span></span> עכשיו פשוט מחלקים את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x) &gt; \\frac{1}{2}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> (שיודעים שהיא חיובית ולכן החלוקה מותרת ושומרת כיוון!), ומקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x) &gt; \\frac{1}{2f(x)}\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=|x|\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(N^*_1(0)\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1+x}{|x|}\\)</span>,</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)=1+x\\to 1\\)</span>.</span></span> אם ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda=0.5\\)</span>,</span> אז לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-0.5, 0.5)\\setminus\\{0\\}\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)=1+x &gt; 0.5\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1+x}{|x|} &gt; \\frac{1}{2|x|}=\\frac{1}{2f(x)}\\)</span>.</span></p>\n<p><strong><span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span></strong> הוא הסביבה המנוקבת סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>:</span> כל הנקודות שמרחקן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>,</span></span> חוץ <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עצמה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\delta\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בדוגמה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=|x|\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1+x}{|x|}\\)</span>:</span></span> העקומה הכחולה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span>,</span> והעקומה האדומה המקווקוות היא הגבול התחתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2f(x)}=\\frac{1}{2|x|}\\)</span>.</span> בתוך החלון שבין שני הקווים הירוקים <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\pm 0.5\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda=0.5\\)</span>),</span> הגרף הכחול נמצא תמיד מעל האדום (ומשמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-0.5\\)</span></span> הכחול יורד מתחת לאדום, לכן חשובה ההצרה לסביבה קטנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda\\)</span>).</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1.2,&quot;xmax&quot;:1.2,&quot;ymin&quot;:-1,&quot;ymax&quot;:10}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{1+x}{|x|}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;lb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\frac{1}{2|x|}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=-0.5&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0.5&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;cross&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(-0.5, 1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הפעלת הגדרת הגבול עם $\\varepsilon=\\frac{1}{2}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הפעלת הגדרת הגבול עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{1}{2}\\)</span></p><div class=\"callout-body\"><p>מה נותנת ההגדרה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)g(x)=1\\)</span> כאשר בוחרים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{1}{2}\\)</span>?</span></p></div></div>"},{"title":"רמז 2: אל תשכחו את התחום $N^*_\\delta(0)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: אל תשכחו את התחום <span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span></p><div class=\"callout-body\"><p>הגדרת הגבול נותנת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span>.</span> כדי שכל נקודה בסביבה המנוקבת אכן תהיה בתחום שבו <span class=\"math math-inline\" dir=\"ltr\">\\(f,g\\)</span> מוגדרות <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f&gt;0\\)</span>,</span></span> בחרו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda = \\min\\{\\delta, \\delta_1\\}\\)</span>!</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפעיל את הגדרת הגבול (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.28\\)</span>)</span> על <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)\\to 1\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{1}{2}\\)</span> ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)g(x)-1|&lt;\\frac{1}{2}\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;|x|&lt;\\delta_1\\)</span> בתחום ההגדרה. נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda = \\min\\{\\delta,\\delta_1\\}&gt;0\\)</span> כדי להישאר בתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span>,</span> נסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)&gt;\\frac{1}{2}\\)</span>,</span> ונחלק <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;0\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>התשובה: הטענה נכונה.</strong></p>\n<p><strong>שלב 1: שימוש בהגדרת הגבול עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)\\)</span>.</span></strong> נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)g(x) = 1\\)</span>.</span> נפעיל את הגדרת הגבול בנקודה (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.28\\)</span>)</span> על הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)g(x)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{1}{2} &gt; 0\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1 &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בתחום ההגדרה של <span class=\"math math-inline\" dir=\"ltr\">\\(fg\\)</span> המקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\delta_1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)g(x) - 1| &lt; \\frac{1}{2},\\]</div>\n<p>כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[1 - \\frac{1}{2} &lt; f(x)g(x) &lt; 1 + \\frac{1}{2}, \\qquad \\text{ובפרט } f(x)g(x) &gt; \\frac{1}{2}.\\]</div>\n<p><strong>שלב 2: שמירה על התחום וחלוקה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>.</span></span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda := \\min\\{\\delta, \\delta_1\\} &gt; 0\\)</span>.</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in N^*_\\lambda(0)\\)</span>.</span> אזי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\lambda \\le \\delta\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in N^*_\\delta(0)\\)</span>,</span> מה שמבטיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span></span> מוגדרות וכי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>.</span> בנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\lambda \\le \\delta_1\\)</span>,</span> ולכן משלב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x) &gt; \\frac{1}{2}\\)</span>.</span></p>\n<p><em>למה?</em> בחרנו את הסביבה הקטנה מבין השתיים כדי שלא נצא במקרה מהטווח שבו מובטח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חיובית, ועדיין נבטיח שהמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(fg\\)</span> כבר גבוהה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span>.</span></span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>,</span></span> ניתן לחלק את שני האגפים של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x) &gt; \\frac{1}{2}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> תוך שמירה על כיוון האי-שוויון:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) &gt; \\frac{1}{2f(x)} \\qquad \\text{לכל } x \\in N^*_\\lambda(0). \\quad \\blacksquare\\]</div></div></div>","steps":["<p><strong>התשובה: הטענה נכונה.</strong></p>\n<p><strong>שלב 1: שימוש בהגדרת הגבול עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x)\\)</span>.</span></strong> נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} f(x)g(x) = 1\\)</span>.</span> נפעיל את הגדרת הגבול בנקודה (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.28\\)</span>)</span> על הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=f(x)g(x)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{1}{2} &gt; 0\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1 &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בתחום ההגדרה של <span class=\"math math-inline\" dir=\"ltr\">\\(fg\\)</span> המקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\delta_1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(x)g(x) - 1| &lt; \\frac{1}{2},\\]</div>\n<p>כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[1 - \\frac{1}{2} &lt; f(x)g(x) &lt; 1 + \\frac{1}{2}, \\qquad \\text{ובפרט } f(x)g(x) &gt; \\frac{1}{2}.\\]</div>","<p><strong>שלב 2: שמירה על התחום וחלוקה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>.</span></span></strong> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda := \\min\\{\\delta, \\delta_1\\} &gt; 0\\)</span>.</span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in N^*_\\lambda(0)\\)</span>.</span> אזי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\lambda \\le \\delta\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in N^*_\\delta(0)\\)</span>,</span> מה שמבטיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span></span> מוגדרות וכי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>.</span> בנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; |x| &lt; \\lambda \\le \\delta_1\\)</span>,</span> ולכן משלב <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x) &gt; \\frac{1}{2}\\)</span>.</span></p>\n<p><em>למה?</em> בחרנו את הסביבה הקטנה מבין השתיים כדי שלא נצא במקרה מהטווח שבו מובטח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חיובית, ועדיין נבטיח שהמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\(fg\\)</span> כבר גבוהה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span>.</span></span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span>,</span></span> ניתן לחלק את שני האגפים של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)g(x) &gt; \\frac{1}{2}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> תוך שמירה על כיוון האי-שוויון:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) &gt; \\frac{1}{2f(x)} \\qquad \\text{לכל } x \\in N^*_\\lambda(0). \\quad \\blacksquare\\]</div>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(\\lambda = \\delta_1\\)</span> (מהגבול בלבד) בלי לקחת מינימום עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> — אילו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1 &gt; \\delta\\)</span>,</span> ייתכן <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\(N^*_{\\delta_1}(0)\\)</span></span> הפונקציות אינן מוגדרות או <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) \\le 0\\)</span>.</span></span></li><li>לשכוח לנמק שמותר לחלק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\)</span></span> מבלי להפוך את האי-שוויון דווקא מפני שנתון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; 0\\)</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N^*_\\delta(0)\\)</span>.</span></span></li></ul></div></div>"},{"label":"ב(1)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כל סדרה ששואפת למספר חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> נכלאת בסוף בין שני מספרים חיוביים קבועים, והשורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י של כל מספר חיובי קבוע שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן סנדוויץ׳ מוחץ גם את <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כל סדרה ששואפת למספר חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> נכלאת בסוף בין שני מספרים חיוביים קבועים, והשורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י של כל מספר חיובי קבוע שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן סנדוויץ׳ מוחץ גם את <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: נחשוב על <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> כמשהו שמצליח בסוף להיכנס למסדרון שבין <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span> לבין <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span> (שניהם חיוביים!). כעת מפעילים על הסדרה ועל קירות המסדרון את המכונה שמכווצת חזקות: שורש מסדר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span> הקיר התחתון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{L/2}\\)</span>)</span> מטפס <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> הקיר העליון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{3L/2}\\)</span>)</span> יורד <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> והסדרה שבאמצע נמחצת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n \\to L = 3\\)</span>,</span> החל ממקום מסוים כל האיברים הם בין <span class=\"math math-inline\" dir=\"ltr\">\\(1.5\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.5\\)</span>.</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=100\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[100]{1.5}\\approx 1.0041\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[100]{4.5}\\approx 1.0152\\)</span>,</span></span> וככל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> גדל שני הצדדים מתכנסים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>משפט הסנדוויץ׳</strong> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.32\\)</span>)</span> מראה שאם סדרה לכודה בין שתי סדרות השואפות לאותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> גם היא חייבת לשאוף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>לדוגמה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n = 3 + \\frac{(-1)^n}{n}\\)</span> (שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=3\\)</span>):</span></span> הקו הכתום <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[x]{4.5}\\)</span> מלמעלה והקו האדום <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[x]{1.5}\\)</span> מלמטה מתקרבים יחד אל הקו הירוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>,</span> ולוכדים ביניהם את הנקודות הכחולות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((n, \\sqrt[n]{a_n})\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.5,&quot;xmax&quot;:14,&quot;ymin&quot;:0.8,&quot;ymax&quot;:2.4}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;up&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=4.5^{1/x}+0\\\\cdot\\\\sqrt{x-1}&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;lo&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1.5^{1/x}+0\\\\cdot\\\\sqrt{x-1}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(2, 3.5^{0.5})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(4, 3.25^{0.25})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p6&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(6, 3.1667^{1/6})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p8&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(8, 3.125^{1/8})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p10&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(10, 3.1^{0.1})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p12&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(12, 3.0833^{1/12})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: חסימת $a_n$ בין שני מספרים חיוביים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: חסימת <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני מספרים חיוביים</p><div class=\"callout-body\"><p>הפעילו את הגדרת הגבול <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2.9\\)</span>)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{L}{2} &gt; 0\\)</span> (מדוע בחרנו דווקא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span>?</span> כדי שגם הקצה התחתון <span class=\"math math-inline\" dir=\"ltr\">\\(L - \\frac{L}{2} = \\frac{L}{2}\\)</span> יישאר חיובי!).</p></div></div>"},{"title":"רמז 2: הוצאת שורש ה-$n$-י וסנדוויץ׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הוצאת שורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י וסנדוויץ׳</p><div class=\"callout-body\"><p>הפעילו את טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.34\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{c}\\to 1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>)</span> על שני הקצוות וסגרו עם משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.32\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>מאפיון הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L &gt; 0\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}\\)</span> נמצא <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; \\frac{L}{2} &lt; a_n &lt; \\frac{3L}{2}\\)</span>.</span> בפרט <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> מוגדר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> והוצאת שורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י מובילה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{L/2} &lt; \\sqrt[n]{a_n} &lt; \\sqrt[n]{3L/2}\\)</span>.</span></span> מטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.34\\)</span> שני הצדדים שואפים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> וממשפט הסנדוויץ׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2.32\\)</span>)</span> גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\to 1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: כליאת <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בסביבה חיובית של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></strong> נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L &gt; 0\\)</span>.</span> נפעיל את הגדרת הגבול (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.9\\)</span>)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{L}{2} &gt; 0\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N \\in \\mathbb{N}\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|a_n - L| &lt; \\frac{L}{2}, \\qquad \\text{כלומר } 0 &lt; \\frac{L}{2} &lt; a_n &lt; \\frac{3L}{2}.\\]</div>\n<p>בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span>,</span> כך שהשורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> מוגדר היטב (וכידוע, שינוי סופי של איברים אינו משנה את קיום הגבול או ערכו — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span></p>\n<p><strong>שלב 2: הוצאת שורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י ומשפט הסנדוויץ׳.</strong> מכיוון שפונקציית השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{\\frac{L}{2}} &lt; \\sqrt[n]{a_n} &lt; \\sqrt[n]{\\frac{3L}{2}}.\\]</div>\n<p><em>למה?</em> משום ששני הגבולות <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span></span> הם מספרים קבועים חיוביים, השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י של כל אחד מהם &quot;נשחק&quot; לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> גדל, וכך סוגר את <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> באמצע.</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2} &gt; 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2} &gt; 0\\)</span>,</span></span> לפי טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.34\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{c} = 1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{\\frac{L}{2}} = 1 \\qquad \\text{וגם} \\qquad \\lim_{n\\to\\infty}\\sqrt[n]{\\frac{3L}{2}} = 1.\\]</div>\n<p>לפי משפט הסנדוויץ׳ (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.32\\)</span>),</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{a_n} = 1\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p></div></div>","steps":["<p><strong>שלב 1: כליאת <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בסביבה חיובית של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></strong> נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = L &gt; 0\\)</span>.</span> נפעיל את הגדרת הגבול (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.9\\)</span>)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{L}{2} &gt; 0\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N \\in \\mathbb{N}\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|a_n - L| &lt; \\frac{L}{2}, \\qquad \\text{כלומר } 0 &lt; \\frac{L}{2} &lt; a_n &lt; \\frac{3L}{2}.\\]</div>\n<p>בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span>,</span> כך שהשורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> מוגדר היטב (וכידוע, שינוי סופי של איברים אינו משנה את קיום הגבול או ערכו — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span></p>","<p><strong>שלב 2: הוצאת שורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י ומשפט הסנדוויץ׳.</strong> מכיוון שפונקציית השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{\\frac{L}{2}} &lt; \\sqrt[n]{a_n} &lt; \\sqrt[n]{\\frac{3L}{2}}.\\]</div>\n<p><em>למה?</em> משום ששני הגבולות <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span></span> הם מספרים קבועים חיוביים, השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י של כל אחד מהם &quot;נשחק&quot; לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> גדל, וכך סוגר את <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> באמצע.</p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2} &gt; 0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2} &gt; 0\\)</span>,</span></span> לפי טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.34\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{c} = 1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{\\frac{L}{2}} = 1 \\qquad \\text{וגם} \\qquad \\lim_{n\\to\\infty}\\sqrt[n]{\\frac{3L}{2}} = 1.\\]</div>\n<p>לפי משפט הסנדוויץ׳ (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.32\\)</span>),</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{a_n} = 1\\)</span>.</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\blacksquare\\)</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = 1\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = \\frac{L}{2}\\)</span>:</span> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L = 0.2\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(L-1 &lt; 0\\)</span> ואי אפשר להוציא שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י ממספר שלילי או להפעיל את טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.34\\)</span> על קבוע שלילי!</li><li>לכתוב ישירות &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim \\sqrt[n]{a_n} = \\lim a_n^{1/n} = L^0 = 1\\)</span>&quot; בלי הוכחה — הטענה עצמה היא מה שצריך להוכיח בסעיף זה!</li></ul></div></div>"},{"label":"ב(2)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">מוציאים את החזקה הכי גבוהה <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> מחוץ לפולינום — ואז השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י מתפרק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt[n]{n})^T\\)</span></span> כפול שורש של משהו ששואף למקדם החיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T\\)</span>,</span> ושני הגורמים שואפים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: מוציאים את החזקה הכי גבוהה <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> מחוץ לפולינום — ואז השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י מתפרק <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt[n]{n})^T\\)</span></span> כפול שורש של משהו ששואף למקדם החיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T\\)</span>,</span> ושני הגורמים שואפים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: בפולינום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T n^T + \\dots + b_0\\)</span>,</span> <span class=\"nobr\">כשה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> נהיה ענק, רק האיבר החזק <span class=\"math math-inline\" dir=\"ltr\">\\(b_T n^T\\)</span> באמת קובע את הגודל; שאר האיברים הופכים לרעש זניח שמתכווץ <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> אם מחלקים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span>.</span></span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^T \\cdot a_n\\)</span>,</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> היא סדרה שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(b_T &gt; 0\\)</span></span> (כמו בסעיף ב(1)!). השורש של מכפלה הוא מכפלת השורשים: אחד הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt[n]{n})^T \\to 1^T = 1\\)</span>,</span> והשני הוא <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n} \\to 1\\)</span> לפי הסעיף הקודם.</p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = 2n^2 - 10n + 3\\)</span>.</span> לאיברים הראשונים <span class=\"math math-inline\" dir=\"ltr\">\\(p(2)=-9\\)</span> שלילי, אבל החל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n=5\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) &gt; 0\\)</span>.</span> נכתוב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^2 \\cdot \\left(2 - \\frac{10}{n} + \\frac{3}{n^2}\\right) = n^2 \\cdot a_n\\)</span>,</span> שבה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n \\to 2 &gt; 0\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)} = (\\sqrt[n]{n})^2 \\cdot \\sqrt[n]{a_n} \\to 1^2 \\cdot 1 = 1\\)</span>.</span></p>\n<p><strong>גורם מוביל</strong> הוא הוצאת החזקה הגבוהה <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> כדי להפריד סדרת חזקה טהורה מסדרה שמתכנסת לגבול סופי חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בדוגמה <span class=\"math math-inline\" dir=\"ltr\">\\(p(n)=2n^2-10n+3\\)</span> (חיובי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ge 5\\)</span>):</span> בכחול העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[x]{2x^2-10x+3}\\)</span> (והנקודות הכחולות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=5, 10, 20\\)</span>),</span></span> שמאחורי רף ההתחלה מתקרבת בהדרגה אל הקו הירוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:3,&quot;xmax&quot;:30,&quot;ymin&quot;:0.6,&quot;ymax&quot;:1.8}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=(2x^{2}-10x+3)^{1/x}+0\\\\cdot\\\\sqrt{x-5}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;y1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(5, 3^{0.2})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p10&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(10, 103^{0.1})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p20&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(20, 603^{0.05})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: להוציא $n^T$ גורם משותף","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: להוציא <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> גורם משותף</p><div class=\"callout-body\"><p>כתבו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^T \\left(b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_0}{n^T}\\right) = n^T \\cdot a_n\\)</span>.</span> מהו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n\\)</span>?</span></p></div></div>"},{"title":"רמז 2: להפריד את השורש ולטפל בשני הגורמים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: להפריד את השורש ולטפל בשני הגורמים</p><div class=\"callout-body\"><p>בדקו תחילה מדוע <span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span> כמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> (כדי <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)}\\)</span></span> יהיה מוגדר!). אחר כך השתמשו בטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{n}\\to 1\\)</span>)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt[n]{n})^T\\)</span> ובסעיף ב<span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוציא <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> גורם משותף ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^T a_n\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n = b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_0}{n^T}\\)</span>.</span> נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n \\to b_T &gt; 0\\)</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(p(n)&gt;0\\)</span> כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span> נפרק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)} = (\\sqrt[n]{n})^T \\cdot \\sqrt[n]{a_n}\\)</span>,</span></span> נשתמש בטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\((\\sqrt[n]{n})^T \\to 1\\)</span> ובסעיף ב<span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n} \\to 1\\)</span>,</span> ונסיק מאריתמטיקה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>)</span> שהגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: פירוק הפולינום ווידוא חיוביות הזנב.</strong> נכתוב לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(n) = n^T \\left(b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_1}{n^{T-1}} + \\frac{b_0}{n^T}\\right) = n^T \\cdot a_n,\\]</div>\n<p>כאשר נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n := b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_1}{n^{T-1}} + \\frac{b_0}{n^T}\\)</span>.</span> (אם <span class=\"math math-inline\" dir=\"ltr\">\\(T=0\\)</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n)=b_0=a_n&gt;0\\)</span>.)</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n^k} = 0\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span> (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(2.43(\\text{ה})\\)</span> על טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.37\\)</span> ומכפלה באריתמטיקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>),</span> מאריתמטיקת גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>)</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} a_n = b_T + 0 + \\dots + 0 = b_T &gt; 0.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T &gt; 0\\)</span>,</span></span> לפי שמירת סימן בגבול (למשל מהגדרה <span class=\"math math-inline\" dir=\"ltr\">\\(2.9\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = b_T\\)</span> או משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.26\\)</span>),</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N \\in \\mathbb{N}\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span>.</span> לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^T a_n &gt; 0\\)</span>,</span> והשורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)}\\)</span> מוגדר היטב לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> (איברים ראשונים סופיים אינם משפיעים על הגבול — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span></p>\n<p><strong>שלב 2: חישוב הגבול בעזרת טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span> וסעיף ב<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span>.</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{p(n)} = \\sqrt[n]{n^T \\cdot a_n} = \\left(\\sqrt[n]{n}\\right)^T \\cdot \\sqrt[n]{a_n}.\\]</div>\n<p><em>למה?</em> הפרדנו את הצמיחה הפולינומית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span>)</span> מהגורם המתייצב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>):</span> הסעיף הקודם פותר אוטומטית את החלק של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>,</span> והשורש של <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ידוע.</p>\n<p>כעת:</p>\n<ul><li>לפי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} \\sqrt[n]{n} = 1\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(T\\)</span></span> הוא מעלה טבעית קבועה (מספר שלם אי-שלילי קבוע), לפי אריתמטיקה של גבולות (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(2.28(\\text{ג})\\)</span> במכפלה של <span class=\"math math-inline\" dir=\"ltr\">\\(T\\)</span> גורמים) מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\left(\\sqrt[n]{n}\\right)^T = 1^T = 1.\\]</div>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = b_T &gt; 0\\)</span>,</span></span> לפי סעיף ב<span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\sqrt[n]{a_n} = 1.\\]</div>\n<p>שוב לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28(\\text{ג})\\)</span>)</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\sqrt[n]{p(n)} = 1 \\cdot 1 = 1. \\quad \\blacksquare\\]</div></div></div>","steps":["<p><strong>שלב 1: פירוק הפולינום ווידוא חיוביות הזנב.</strong> נכתוב לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n \\in \\mathbb{N}\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[p(n) = n^T \\left(b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_1}{n^{T-1}} + \\frac{b_0}{n^T}\\right) = n^T \\cdot a_n,\\]</div>\n<p>כאשר נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n := b_T + \\frac{b_{T-1}}{n} + \\dots + \\frac{b_1}{n^{T-1}} + \\frac{b_0}{n^T}\\)</span>.</span> (אם <span class=\"math math-inline\" dir=\"ltr\">\\(T=0\\)</span> מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n)=b_0=a_n&gt;0\\)</span>.)</span></p>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n^k} = 0\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\ge 1\\)</span> (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(2.43(\\text{ה})\\)</span> על טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.37\\)</span> ומכפלה באריתמטיקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>),</span> מאריתמטיקת גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>)</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} a_n = b_T + 0 + \\dots + 0 = b_T &gt; 0.\\]</div>\n<p>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_T &gt; 0\\)</span>,</span></span> לפי שמירת סימן בגבול (למשל מהגדרה <span class=\"math math-inline\" dir=\"ltr\">\\(2.9\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon = b_T\\)</span> או משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.26\\)</span>),</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N \\in \\mathbb{N}\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n &gt; 0\\)</span>.</span> לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(p(n) = n^T a_n &gt; 0\\)</span>,</span> והשורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)}\\)</span> מוגדר היטב לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> (איברים ראשונים סופיים אינם משפיעים על הגבול — משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>).</span></p>","<p><strong>שלב 2: חישוב הגבול בעזרת טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span> וסעיף ב<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span>.</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n &gt; N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{p(n)} = \\sqrt[n]{n^T \\cdot a_n} = \\left(\\sqrt[n]{n}\\right)^T \\cdot \\sqrt[n]{a_n}.\\]</div>\n<p><em>למה?</em> הפרדנו את הצמיחה הפולינומית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span>)</span> מהגורם המתייצב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>):</span> הסעיף הקודם פותר אוטומטית את החלק של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span>,</span> והשורש של <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ידוע.</p>\n<p>כעת:</p>\n<ul><li>לפי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.35\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} \\sqrt[n]{n} = 1\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(T\\)</span></span> הוא מעלה טבעית קבועה (מספר שלם אי-שלילי קבוע), לפי אריתמטיקה של גבולות (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(2.28(\\text{ג})\\)</span> במכפלה של <span class=\"math math-inline\" dir=\"ltr\">\\(T\\)</span> גורמים) מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\left(\\sqrt[n]{n}\\right)^T = 1^T = 1.\\]</div>\n<ul><li>מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} a_n = b_T &gt; 0\\)</span>,</span></span> לפי סעיף ב<span class=\"math math-inline\" dir=\"ltr\">\\((1)\\)</span> מתקיים:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\sqrt[n]{a_n} = 1.\\]</div>\n<p>שוב לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28(\\text{ג})\\)</span>)</span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty} \\sqrt[n]{p(n)} = 1 \\cdot 1 = 1. \\quad \\blacksquare\\]</div>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח לבדוק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(p(n) &gt; 0\\)</span></span> החל ממקום מסוים: המקדמים הנמוכים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(b_{T-1},\\dots,b_0\\)</span>)</span> עלולים להיות שליליים ולגרום לאיברים הראשונים להיות שליליים (כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{p(n)}\\)</span></span> לזוגי כלל לא מוגדר בהתחלה), ורק הסימן <span class=\"math math-inline\" dir=\"ltr\">\\(b_T &gt; 0\\)</span> מבטיח זנב חיובי.</li><li>לטעון &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty} \\sqrt[n]{p(n)} = \\lim \\sqrt[n]{n^T} \\dots\\)</span>&quot; תוך סכימה של אינסוף גבולות או ניסיון לשמור על שאר האיברים בתוך שורש בנפרד: חייבים להוציא <span class=\"math math-inline\" dir=\"ltr\">\\(n^T\\)</span> כגורם <strong>כפלי</strong>, כי השורש מתפרק על כפל (ולא על חיבור!).</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0} (1+x^2)^{\\frac{1}{\\sin(x^2)+\\cos x - 1}}\\)</span> הוא</p>\n<p>א. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p>ב. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p>ג. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<p>ד. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>.</span></p>\n<p>ה. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></p>\n<p>ו. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>.</span></p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הופכים את החזקה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> בחזקת לוגריתם ומחלקים מונה ומכנה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>:</span></span> למעלה מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ולמטה מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1 - \\frac{1}{2} = \\frac{1}{2}\\)</span>,</span> ולכן המעריך שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> והגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הופכים את החזקה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> בחזקת לוגריתם ומחלקים מונה ומכנה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>:</span></span> למעלה מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ולמטה מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1 - \\frac{1}{2} = \\frac{1}{2}\\)</span>,</span> ולכן המעריך שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> והגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: זו צורה קלאסית של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span>:</span> הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\(1+x^2\\)</span> קרוב מאוד <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> והחזקה ענקית. המעבר לצורת <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> מתרגם את התחרות בין שניהם לשאלה פשוטה: כמה מהר <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> מתאפס לעומת המכנה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)+\\cos x-1\\)</span>?</span> משני הגבולות הטריגונומטריים הידועים, <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)\\)</span> מתנהג קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\cos x - 1\\)</span></span> מתנהג כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{2}x^2\\)</span>,</span> כך שיחד המכנה הוא כמו חצי <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> — והמנה יוצאת פי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: נציב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+x^2 = 1.01\\)</span>.</span> במכנה המעריך: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(0.01) + \\cos(0.1) - 1 \\approx 0.0100 - 0.0050 = 0.0050\\)</span>.</span> לכן המעריך הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\approx \\frac{1}{0.005} = 200\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1.01^{200} \\approx (1.01^{100})^2 \\approx e^2 \\approx 7.39\\)</span>.</span></span></p>\n<p><strong>אי-ודאות מסוג <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span></strong> אינה נותנת בהכרח <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> — הערך תלוי ביחס שבין הסטייה של הבסיס <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> לבין קצב השאיפה של החזקה לאינסוף.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הגרף של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=(1+x^2)^{\\frac{1}{\\sin(x^2)+\\cos x-1}}\\)</span> סביב הראשית (חור פתוח <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,e^2)\\)</span>),</span></span> ובאדום הקו האופקי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=e^2 \\approx 7.389\\)</span>.</span> משני הצדדים של <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הגרף מתקרב בדיוק לגובה האדום.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1,&quot;xmax&quot;:1,&quot;ymin&quot;:5,&quot;ymax&quot;:9}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=(1+x^{2})^{\\\\frac{1}{\\\\sin(x^{2})+\\\\cos(x)-1}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;ye2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=e^{2}&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;hole&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0, e^{2})&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מעבר להצגה מעריכית $e^{\\dots}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מעבר להצגה מעריכית <span class=\"math math-inline\" dir=\"ltr\">\\(e^{\\dots}\\)</span></p><div class=\"callout-body\"><p>כתבו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = \\exp\\left(\\frac{\\ln(1+x^2)}{\\sin(x^2)+\\cos x-1}\\right)\\)</span>.</span> כדי לזהות את קצב ההתאפסות, חלקו גם את המונה וגם את המכנה של השבר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>.</span></span></p></div></div>"},{"title":"רמז 2: שני גבולות ידועים ל-$x^2$ במכנה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שני גבולות ידועים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> במכנה</p><div class=\"callout-body\"><p>השמשו <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{u\\to 0}\\frac{\\sin u}{u}=1\\)</span></span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.45\\)</span>)</span> ובזהות <span class=\"math math-inline\" dir=\"ltr\">\\(1-\\cos x = 2\\sin^2\\left(\\frac{x}{2}\\right)\\)</span> כדי למצוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{\\sin(x^2)+\\cos x-1}{x^2} = 1-\\frac{1}{2}=\\frac{1}{2}\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפרק את המכנה לאחר חלוקה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>:</span></span> נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(x^2)+\\cos x-1}{x^2}\\to 1-\\frac{1}{2}=\\frac{1}{2}\\)</span></span> (ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(4.45\\)</span> וזהות חצי הזווית, מה שמבטיח גם שהמכנה חיובי בסביבה מנוקבת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span> נעבור להצגה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{\\frac{\\ln(1+x^2)/x^2}{(\\sin(x^2)+\\cos x-1)/x^2}}\\)</span>,</span> נראה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\ln(1+x^2)}{x^2}\\to 1\\)</span>,</span></span> ומאריתמטיקה ורציפות <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: גבול המכנה חלקי <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> (והגדרה היטב סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span> נפרק:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{\\sin(x^2)+\\cos x-1}{x^2} = \\frac{\\sin(x^2)}{x^2} - \\frac{1-\\cos x}{x^2}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\to 0\\)</span>,</span></span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(u=x^2 \\to 0\\)</span> (והוא אינו <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בסביבה מנוקבת), ולכן לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.45\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{\\sin(x^2)}{x^2} = 1.\\]</div>\n<p>עבור האיבר השני, נשתמש בזהות הטריגונומטרית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-\\cos x = 2\\sin^2\\left(\\frac{x}{2}\\right)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{1-\\cos x}{x^2} = \\frac{2\\sin^2(x/2)}{x^2} = \\frac{1}{2}\\left(\\frac{\\sin(x/2)}{x/2}\\right)^2 \\xrightarrow[x\\to 0]{} \\frac{1}{2}\\cdot 1^2 = \\frac{1}{2}.\\]</div>\n<p>לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.38\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0} \\frac{\\sin(x^2)+\\cos x-1}{x^2} = 1 - \\frac{1}{2} = \\frac{1}{2}.\\]</div>\n<p>בפרט, קיימת סביבה מנוקבת של <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> שבה המנה חיובית, ולכן גם המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)+\\cos x-1 &gt; 0\\)</span> והחזקה מוגדרת היטב שם.</p>\n<p><strong>שלב 2: גבול המונה (הלוגריתם) וחישוב סופי.</strong> בסביבה זו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+x^2 &gt; 1 &gt; 0\\)</span>,</span> ולכן ניתן לרשום:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1+x^2)^{\\frac{1}{\\sin(x^2)+\\cos x-1}} = \\exp\\left(\\frac{\\frac{\\ln(1+x^2)}{x^2}}{\\frac{\\sin(x^2)+\\cos x-1}{x^2}}\\right).\\]</div>\n<p>עבור המונה של השבר הפנימי, נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=x^2 \\to 0^+\\)</span>:</span> לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(7.29\\)</span> (או כלל לופיטל <span class=\"math math-inline\" dir=\"ltr\">\\(8.13\\)</span> / <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.14\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{u\\to 0^+}\\frac{\\ln(1+u)}{u} = \\lim_{u\\to 0^+}\\frac{1/(1+u)}{1}=1\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0} \\frac{\\ln(1+x^2)}{x^2} = 1.\\]</div>\n<p><em>למה?</em> משום שגם הבסיס סוטה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בשיעור של בערך <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> וגם המכנה של המעריך מתנהג כחצי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>,</span> היחס שבין &quot;סטייה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span>&quot; ל&quot;מהירות המכנה&quot; הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> חלקי חצי — כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<p>לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.38\\)</span>),</span> המעריך שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1/2} = 2\\)</span>.</span></span> מכיוון שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\exp(t)=e^t\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span></span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6.9\\)</span>),</span> לפי רציפות ההרכבה (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.15\\)</span> / <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.39\\)</span>)</span> הגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: ה.</p></div></div>","steps":["<p><strong>שלב 1: גבול המכנה חלקי <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> (והגדרה היטב סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\ne 0\\)</span> נפרק:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{\\sin(x^2)+\\cos x-1}{x^2} = \\frac{\\sin(x^2)}{x^2} - \\frac{1-\\cos x}{x^2}.\\]</div>\n<p><span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\to 0\\)</span>,</span></span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(u=x^2 \\to 0\\)</span> (והוא אינו <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בסביבה מנוקבת), ולכן לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.45\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{\\sin(x^2)}{x^2} = 1.\\]</div>\n<p>עבור האיבר השני, נשתמש בזהות הטריגונומטרית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-\\cos x = 2\\sin^2\\left(\\frac{x}{2}\\right)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{1-\\cos x}{x^2} = \\frac{2\\sin^2(x/2)}{x^2} = \\frac{1}{2}\\left(\\frac{\\sin(x/2)}{x/2}\\right)^2 \\xrightarrow[x\\to 0]{} \\frac{1}{2}\\cdot 1^2 = \\frac{1}{2}.\\]</div>\n<p>לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.38\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0} \\frac{\\sin(x^2)+\\cos x-1}{x^2} = 1 - \\frac{1}{2} = \\frac{1}{2}.\\]</div>\n<p>בפרט, קיימת סביבה מנוקבת של <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> שבה המנה חיובית, ולכן גם המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(x^2)+\\cos x-1 &gt; 0\\)</span> והחזקה מוגדרת היטב שם.</p>","<p><strong>שלב 2: גבול המונה (הלוגריתם) וחישוב סופי.</strong> בסביבה זו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+x^2 &gt; 1 &gt; 0\\)</span>,</span> ולכן ניתן לרשום:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1+x^2)^{\\frac{1}{\\sin(x^2)+\\cos x-1}} = \\exp\\left(\\frac{\\frac{\\ln(1+x^2)}{x^2}}{\\frac{\\sin(x^2)+\\cos x-1}{x^2}}\\right).\\]</div>\n<p>עבור המונה של השבר הפנימי, נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=x^2 \\to 0^+\\)</span>:</span> לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(7.29\\)</span> (או כלל לופיטל <span class=\"math math-inline\" dir=\"ltr\">\\(8.13\\)</span> / <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.14\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{u\\to 0^+}\\frac{\\ln(1+u)}{u} = \\lim_{u\\to 0^+}\\frac{1/(1+u)}{1}=1\\)</span>):</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0} \\frac{\\ln(1+x^2)}{x^2} = 1.\\]</div>\n<p><em>למה?</em> משום שגם הבסיס סוטה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בשיעור של בערך <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> וגם המכנה של המעריך מתנהג כחצי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>,</span> היחס שבין &quot;סטייה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span>&quot; ל&quot;מהירות המכנה&quot; הוא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> חלקי חצי — כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></p>\n<p>לפי אריתמטיקה של גבולות (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.38\\)</span>),</span> המעריך שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1/2} = 2\\)</span>.</span></span> מכיוון שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\exp(t)=e^t\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span></span> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6.9\\)</span>),</span> לפי רציפות ההרכבה (משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.15\\)</span> / <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(4.39\\)</span>)</span> הגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: ה.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1-\\cos x\\)</span></span> שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בקצב מהיר יותר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> ולשכוח את <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{2}\\)</span></span> במכנה (ואז לקבל <span class=\"math math-inline\" dir=\"ltr\">\\(e^1=e\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^2\\)</span>).</span></li><li>לשכוח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span></span> היא צורה בלתי-מוגדרת ולנחש שהגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"answer":"ה"}},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> הסדרה שאיבריה הם: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2,\\ 1+\\frac{1}{2},\\ 3,\\ 1+\\frac{1}{3},\\ 4,\\ 1+\\frac{1}{4},\\ 5,\\ 1+\\frac{1}{5},\\ \\dots\\)</span>.</span> אז</p>\n<p>א. <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת במובן הרחב.</p>\n<p>ב. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\sup\\{a_n \\mid n \\in \\mathbb{N}\\}\\)</span>.</span></p>\n<p>ג. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = \\min\\{a_n \\mid n \\in \\mathbb{N}\\}\\)</span>.</span></p>\n<p>ד. לסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> יש לפחות <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים.</p>\n<p>ה. כל הטענות הנ״ל אינן נכונות.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הסדרה מתפצלת לשני זרמים בלבד — הזרם האי-זוגי שטס <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span> והזרם הזוגי שנוחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן אין לה מקסימום/סופרמום, אין מינימום בקבוצת הערכים, ויש לה רק שני גבולות חלקיים.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הסדרה מתפצלת לשני זרמים בלבד — הזרם האי-זוגי שטס <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span> והזרם הזוגי שנוחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן אין לה מקסימום/סופרמום, אין מינימום בקבוצת הערכים, ויש לה רק שני גבולות חלקיים.</p>\n<p><strong>תמונה בראש</strong>: תארו מכונה שזורקת לסל שני סוגי כדורים לסירוגין: זוגי מתקרב כל פעם קצת יותר <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מלמעלה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(1.5, 1.33, 1.25\\dots\\)</span>),</span> ואי-זוגי מטפס למעלה בלי תקרה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2, 3, 4, 5\\dots\\)</span>).</span> בגלל שני הזרמים האלה, הסדרה לא הולכת ליעד אחד, לא נחסמת מלמעלה, והמספר <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> הוא הרצפה שאליה מתקרבים אבל הוא עצמו לעולם אינו נופל לתוך הסל (כך שאין איבר מינימלי!).</p>\n<p><strong>עם מספרים</strong>: האיברים במקומות הזוגיים הם <span class=\"math math-inline\" dir=\"ltr\">\\(1.5, 1.333, 1.25, 1.2 \\dots\\)</span> — כולם <strong>גדולים ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span></strong>! האיברים האי-זוגיים הם <span class=\"math math-inline\" dir=\"ltr\">\\(2, 3, 4, 5 \\dots\\)</span> — גם הם גדולים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> אינו ברשימת האיברים, ואין ברשימה אף איבר קטן מכולם (המינימום אינו קיים).</p>\n<p><strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\min A\\)</span></strong> חייב להיות איבר <strong>שנמצא בתוך הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></strong> עצמה, בניגוד <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf A\\)</span></span> שיכול להיות רק גבול שמבחוץ. <strong><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A\\)</span></strong> (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>)</span> קיים רק <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> חסומה מלעיל.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הנקודות הכחולות במקומות האי-זוגיים מטפסות בקו ישר <span class=\"math math-inline\" dir=\"ltr\">\\(2,3,4,5\\dots\\)</span> לאינסוף, והנקודות האדומות במקומות הזוגיים יורדות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1.5\\)</span></span> לכיוון הקו הירוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>,</span> אבל תמיד נשארות מעליו ולא מגיעות אליו ממש.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:11,&quot;ymin&quot;:0.5,&quot;ymax&quot;:6.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;y1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;o1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 2)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;e1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(2, 1.5)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;o2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(3, 3)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;e2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(4, 1.3333)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;o3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(5, 4)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;e3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(6, 1.25)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;o4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(7, 5)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;e4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(8, 1.2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;o5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(9, 6)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;e5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(10, 1.1667)&quot;,&quot;color&quot;:&quot;#c74440&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: פיצול לשתי תתי-סדרות מכסות (טענה $3.30$)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: פיצול לשתי תתי-סדרות מכסות (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>)</span></p><div class=\"callout-body\"><p>מהו הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k-1})\\)</span> ומהו הגבול של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k})\\)</span>?</span> לפי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>,</span> קבוצת הגבולות החלקיים היא בדיוק איחוד קבוצות הגבולות החלקיים של שתיהן.</p></div></div>"},{"title":"רמז 2: למה $\\sup$ ו-$\\min$ לא קיימים כאן","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\min\\)</span></span> לא קיימים כאן</p><div class=\"callout-body\"><p>שימו לב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{a_n\\mid n\\in\\mathbb{N}\\}\\)</span></span> אינה חסומה מלעיל (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>),</span> ושאף איבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> אינו שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (וגם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+1}\\)</span> יש איבר קטן ממנו, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+2}\\)</span>)!</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ננתח את הסדרה באמצעות תתי-הסדרות האי-זוגית והזוגית <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1}=k+1\\to\\infty\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k}=1+\\frac{1}{k+1}\\to 1\\)</span>).</span></span> מטענה <span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span> נסיק שקבוצת הגבולות החלקיים היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,\\infty\\}\\)</span>,</span> ומכאן נבדוק ונפריך בשיטתיות את כל אחת מהטענות א–ד.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>נרשום את נוסחת הסדרה לפי זוגיות האינדקס: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1} = k+1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k} = 1 + \\frac{1}{k+1}\\)</span>.</span></span></p>\n<p><strong>שלב 1: שלילת טענה א.</strong> תת-הסדרה האי-זוגית <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k-1})=(2,3,4,\\dots)\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> (טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.37\\)</span> + משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>),</span> ואילו תת-הסדרה הזוגית <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac{1}{k+1}\\right)\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(2.43(\\text{ה})\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>).</span></span> מכיוון שלשתי תתי-סדרות יש גבולות שונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty \\ne 1\\)</span>),</span> הסדרה אינה מתכנסת במובן הרחב. טענה א שגויה.</p>\n<p><strong>שלב 2: שלילת טענה ב.</strong> קבוצת ערכי הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(A = \\{a_n \\mid n \\in \\mathbb{N}\\}\\)</span> אינה חסומה מלעיל (שכן האיברים <span class=\"math math-inline\" dir=\"ltr\">\\(k+1\\)</span> עוברים כל מספר ממשי). לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>,</span> חסם עליון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A\\)</span>)</span> קיים רק עבור קבוצה לא-ריקה <strong>החסומה מלעיל</strong> (ואז הוא מספר ממשי), ולכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> כלל אין חסם עליון (בעוד <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\infty\\)</span></span> במובן הרחב לפי הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.42\\)</span>).</span> השוויון ב שגוי.</p>\n<p><strong>שלב 3: שלילת טענה ג.</strong> קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k-1})\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{\\infty\\}\\)</span>,</span> וקבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k})\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1\\}\\)</span>.</span> לפי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>,</span> קבוצת כל הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> היא האיחוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,\\infty\\}\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 1\\)</span> (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.42\\)</span>).</span> מאידך, כל איבר בסדרה גדול ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k+1 \\ge 2 &gt; 1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+1} &gt; 1\\)</span>),</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1 \\notin A\\)</span>.</span></span> יתרה מזו, לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> כלל אין איבר מינימלי (לכל איבר אי-זוגי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k+1 &gt; 1.5 = a_2\\)</span>,</span> ולכל איבר זוגי <span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+1}\\)</span> קיים איבר קטן ממנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+2}\\)</span>).</span> לכן הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\min\\{a_n\\}\\)</span> כלל אינו קיים (ובודאי אינו שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span></span> טענה ג שגויה.</p>\n<p><em>למה?</em> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> הוא האינפימום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf A=1\\)</span>)</span> — הקו שאליו יורדים, אבל לא דורכים עליו אף פעם; מינימום דורש שהאיבר הקטן ביותר יימצא ממש בתוך הקבוצה.</p>\n<p><strong>שלב 4: שלילת טענה ד ומסקנה.</strong> כאמור מטענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>,</span> קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> (אפילו במובן הרחב) היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,\\infty\\}\\)</span> בלבד — שני גבולות חלקיים, ולא לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>.</span> טענה ד שגויה.</p>\n<p>מכאן שכל ארבע הטענות א–ד אינן נכונות, ולכן הטענה הנכונה היא ה.</p>\n<p><strong>התשובה במבחן</strong>: ה.</p></div></div>","steps":["<p>נרשום את נוסחת הסדרה לפי זוגיות האינדקס: לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k \\in \\mathbb{N}\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k-1} = k+1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{2k} = 1 + \\frac{1}{k+1}\\)</span>.</span></span></p>\n<p><strong>שלב 1: שלילת טענה א.</strong> תת-הסדרה האי-זוגית <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k-1})=(2,3,4,\\dots)\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></span> (טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2.37\\)</span> + משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.17\\)</span>),</span> ואילו תת-הסדרה הזוגית <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac{1}{k+1}\\right)\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(2.43(\\text{ה})\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2.28\\)</span>).</span></span> מכיוון שלשתי תתי-סדרות יש גבולות שונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\infty \\ne 1\\)</span>),</span> הסדרה אינה מתכנסת במובן הרחב. טענה א שגויה.</p>","<p><strong>שלב 2: שלילת טענה ב.</strong> קבוצת ערכי הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(A = \\{a_n \\mid n \\in \\mathbb{N}\\}\\)</span> אינה חסומה מלעיל (שכן האיברים <span class=\"math math-inline\" dir=\"ltr\">\\(k+1\\)</span> עוברים כל מספר ממשי). לפי משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.6\\)</span>,</span> חסם עליון <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A\\)</span>)</span> קיים רק עבור קבוצה לא-ריקה <strong>החסומה מלעיל</strong> (ואז הוא מספר ממשי), ולכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> כלל אין חסם עליון (בעוד <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\overline{\\lim}_{n\\to\\infty} a_n = \\infty\\)</span></span> במובן הרחב לפי הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.42\\)</span>).</span> השוויון ב שגוי.</p>","<p><strong>שלב 3: שלילת טענה ג.</strong> קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k-1})\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{\\infty\\}\\)</span>,</span> וקבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_{2k})\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1\\}\\)</span>.</span> לפי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>,</span> קבוצת כל הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> היא האיחוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,\\infty\\}\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim}_{n\\to\\infty} a_n = 1\\)</span> (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.42\\)</span>).</span> מאידך, כל איבר בסדרה גדול ממש <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(k+1 \\ge 2 &gt; 1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+1} &gt; 1\\)</span>),</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1 \\notin A\\)</span>.</span></span> יתרה מזו, לקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> כלל אין איבר מינימלי (לכל איבר אי-זוגי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k+1 &gt; 1.5 = a_2\\)</span>,</span> ולכל איבר זוגי <span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+1}\\)</span> קיים איבר קטן ממנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{k+2}\\)</span>).</span> לכן הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\min\\{a_n\\}\\)</span> כלל אינו קיים (ובודאי אינו שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>).</span></span> טענה ג שגויה.</p>\n<p><em>למה?</em> המספר <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> הוא האינפימום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf A=1\\)</span>)</span> — הקו שאליו יורדים, אבל לא דורכים עליו אף פעם; מינימום דורש שהאיבר הקטן ביותר יימצא ממש בתוך הקבוצה.</p>","<p><strong>שלב 4: שלילת טענה ד ומסקנה.</strong> כאמור מטענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3.30\\)</span>,</span> קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> (אפילו במובן הרחב) היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,\\infty\\}\\)</span> בלבד — שני גבולות חלקיים, ולא לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>.</span> טענה ד שגויה.</p>\n<p>מכאן שכל ארבע הטענות א–ד אינן נכונות, ולכן הטענה הנכונה היא ה.</p>\n<p><strong>התשובה במבחן</strong>: ה.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לבלבל בין <span class=\"math math-inline\" dir=\"ltr\">\\(\\min A\\)</span> לבין <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf A\\)</span>:</span> כאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\underline{\\lim} a_n = 1 = \\inf A\\)</span>,</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(\\min A\\)</span> <strong>אינו קיים</strong> כי <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> לא מופיע בסדרה.</li><li>לכתוב <span class=\"math math-inline\" dir=\"ltr\">\\(\\sup\\{a_n\\} = \\infty\\)</span> ולהאמין שטענה ב נכונה.</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/29/q6\">2024א · מועד 81, שאלה 6</a>, <a href=\"#/exams/8/q5\">2021א · מועד 81, שאלה 5</a></p>","mc":{"answer":"ה"}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> אם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x\\)</span> אז קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x + c\\)</span>.</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span> אם לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,b)\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x\\)</span> אז קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (a,b)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x + c\\)</span>.</span> אז:</p>\n<p>א. רק טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה.</p>\n<p>ב. רק טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> נכונה.</p>\n<p>ג. שתי הטענות נכונות.</p>\n<p>ד. שתי הטענות אינן נכונות.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה כי בקטע הסגור ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-x\\)</span> מקבל מינימום חיובי שאפשר לדחוף ביניהם; טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> אינה נכונה כי בקצה הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> יכולה לגעת בישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>,</span> כך שהרווח מתכווץ לאפס.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה כי בקטע הסגור ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-x\\)</span> מקבל מינימום חיובי שאפשר לדחוף ביניהם; טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> אינה נכונה כי בקצה הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> יכולה לגעת בישר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>,</span> כך שהרווח מתכווץ לאפס.</p>\n<p><strong>תמונה בראש</strong>: נמדוד את המרחק האנכי <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-x\\)</span> בין גרף הפונקציה לישר האלכסוני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span>.</span> בטענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> הגרף נמצא מעל האלכסון גם בשני הקירות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>:</span></span> כיון שההפרש רציף על קטע סגור, חייב להיות מקום שבו הרווח הכי קטן, וגם שם הוא חיובי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(m&gt;0\\)</span>)</span> — ואז אפשר להשחיל מרווח קבוע (נגיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=\\frac{m}{2}\\)</span>)</span> לאורך כל הקטע! לעומת זאת בטענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> מותר <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> לגעת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span></span> ממש על הקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=b\\)</span>:</span> בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> היא עדיין מעליו, אבל הרווח הולך ונעלם עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> אז שום מרווח חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> לא נכנס מתחתיה לכל הקטע!</p>\n<p><strong>עם מספרים</strong>: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1\\)</span> (קבועה ורציפה!). לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1&gt;x\\)</span>,</span> ובכך עומדת בתנאי טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span> אבל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=1\\)</span>,</span> והרווח <span class=\"math math-inline\" dir=\"ltr\">\\(1-x\\)</span> מתאפס <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 1^-\\)</span>.</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> שתבחרו, אם נציב <span class=\"math math-inline\" dir=\"ltr\">\\(x=1-\\frac{c}{2}\\)</span> (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;1\\)</span>),</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1 &lt; 1+\\frac{c}{2} = x+c\\)</span>,</span> כך ששום <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> לא עובד!</p>\n<p><strong>מינימום על קטע סגור</strong> (משפט ויירשטראס השני, משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.37\\)</span>)</span> מובטח בקטע סגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> אבל אינו מובטח בקטע פתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>משמאל לימין בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>:</span> הקו הירוק <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> הוא האלכסון. הפונקציה הכתומה <span class=\"math math-inline\" dir=\"ltr\">\\(y=x+0.4\\)</span> (טענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> תמיד מעל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> גם בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>)</span></span> משאירה רווח בטוח שאפשר להכניס בו את הקו האפור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x+c\\)</span>.</span> לעומתה הפונקציה הכחולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1\\)</span> (דוגמה נגדית לטענה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>)</span> נמצאת מעל האלכסון בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> אך פוגעת בו <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((1,1)\\)</span></span> — ולכן עוברת מתחת לקו האדום המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(y=x+0.2\\)</span> סמוך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.15,&quot;ymin&quot;:-0.1,&quot;ymax&quot;:1.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;diag&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#388c46&quot;},{&quot;id&quot;:&quot;t1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x+0.4&quot;,&quot;color&quot;:&quot;#fa7e19&quot;},{&quot;id&quot;:&quot;t2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;shift&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x+0.2&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;touch&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הפונקציה הנכונה לבדוק בטענה $1$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הפונקציה הנכונה לבדוק בטענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></p><div class=\"callout-body\"><p>הגדירו <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=f(x)-x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> איזה משפט מבטיח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> מקבלת את ערכה המינימלי, ואיזה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> תבחרו כדי לקבל אי-שוויון <strong>חזק</strong> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(&gt;\\)</span>)</span> ממינימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m\\)</span>?</span></p></div></div>"},{"title":"רמז 2: למה הקצה ההפתוח שובר את טענה $2$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: למה הקצה ההפתוח שובר את טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></p><div class=\"callout-body\"><p>נסו <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=b\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> או פונקציה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> שמקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(b)=b\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)&gt;x\\)</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>לטענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=f(x)-x\\)</span> הרציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> נקבל ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.37\\)</span> מינימום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m=g(x_0)&gt;0\\)</span>,</span> ונבחר <span class=\"math math-inline\" dir=\"ltr\">\\(c=\\frac{m}{2}&gt;0\\)</span> כדי להבטיח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\ge m &gt; c\\)</span>.</span> לטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> ניתן דוגמה נגדית פשוטה: <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ונפריך קיום <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> על ידי בחירת <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0,1)\\)</span> קרוב <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(x) = f(x) - x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נתונה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ולכן לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.11\\)</span> גם הפרשן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציף בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.37\\)</span>),</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in [a,b]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מקבלת את המינימום שלה בקטע, כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) \\ge g(x_0) \\qquad \\text{לכל } x \\in [a,b].\\]</div>\n<p>מכיוון שנתון <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>,</span> מתקיים בפרט בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in [a,b]\\)</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m := g(x_0) = f(x_0) - x_0 &gt; 0\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c := \\frac{m}{2} &gt; 0\\)</span>.</span> אזי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) - x = g(x) \\ge m &gt; \\frac{m}{2} = c \\implies f(x) &gt; x + c.\\]</div>\n<p><em>למה?</em> בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חייבת להשיג ערך נמוך ביותר ממש בתוך הקטע (כולל הקצוות), והוא חיובי ממש. חצי מהרווח הצר ביותר הזה נשאר תמיד קטן ממנו, ולכן נכנס במרווח לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>.</span></p>\n<p><strong>שלב 2: טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> אינה נכונה.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\([a,b] = [0,1]\\)</span> ונגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [0,1]\\)</span>.</span> אזי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = 1 &gt; x\\)</span>,</span> כלומר כל תנאי טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מתקיימים. נניח בשלילה שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x + c\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0,1)\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c \\ge 1\\)</span>,</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x = \\frac{1}{2} \\in (0,1)\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x + c \\ge \\frac{3}{2} &gt; 1 = f(\\frac{1}{2})\\)</span>,</span> סתירה.</li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; c &lt; 1\\)</span>,</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x = 1 - \\frac{c}{2} \\in (0,1)\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x + c = 1 + \\frac{c}{2} &gt; 1 = f(x)\\)</span>,</span> סתירה.</li></ul>\n<p>מכאן שאין קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> מתאים, וטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> שגויה.</p>\n<p>לכן רק טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה.</p>\n<p><strong>התשובה במבחן</strong>: א.</p></div></div>","steps":["<p><strong>שלב 1: טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(g(x) = f(x) - x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נתונה רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ולכן לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.11\\)</span> גם הפרשן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציף בקטע הסגור והחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי המשפט השני של ויירשטראס (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.37\\)</span>),</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in [a,b]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מקבלת את המינימום שלה בקטע, כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x) \\ge g(x_0) \\qquad \\text{לכל } x \\in [a,b].\\]</div>\n<p>מכיוון שנתון <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>,</span> מתקיים בפרט בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in [a,b]\\)</span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(m := g(x_0) = f(x_0) - x_0 &gt; 0\\)</span>.</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c := \\frac{m}{2} &gt; 0\\)</span>.</span> אזי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [a,b]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) - x = g(x) \\ge m &gt; \\frac{m}{2} = c \\implies f(x) &gt; x + c.\\]</div>\n<p><em>למה?</em> בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חייבת להשיג ערך נמוך ביותר ממש בתוך הקטע (כולל הקצוות), והוא חיובי ממש. חצי מהרווח הצר ביותר הזה נשאר תמיד קטן ממנו, ולכן נכנס במרווח לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>.</span></p>","<p><strong>שלב 2: טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> אינה נכונה.</strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\([a,b] = [0,1]\\)</span> ונגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in [0,1]\\)</span>.</span> אזי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ולכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x) = 1 &gt; x\\)</span>,</span> כלומר כל תנאי טענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> מתקיימים. נניח בשלילה שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x) &gt; x + c\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0,1)\\)</span>.</span></p>\n<ul><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c \\ge 1\\)</span>,</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x = \\frac{1}{2} \\in (0,1)\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x + c \\ge \\frac{3}{2} &gt; 1 = f(\\frac{1}{2})\\)</span>,</span> סתירה.</li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 &lt; c &lt; 1\\)</span>,</span> נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x = 1 - \\frac{c}{2} \\in (0,1)\\)</span>.</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x + c = 1 + \\frac{c}{2} &gt; 1 = f(x)\\)</span>,</span> סתירה.</li></ul>\n<p>מכאן שאין קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c &gt; 0\\)</span> מתאים, וטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> שגויה.</p>\n<p>לכן רק טענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> נכונה.</p>\n<p><strong>התשובה במבחן</strong>: א.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לבחור בטענה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c = m = g(x_0)\\)</span>:</span> אז בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0) = x_0 + c\\)</span> ולא אי-שוויון חזק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0) &gt; x_0 + c\\)</span>!</span> יש לקחת מספר קטן יותר, למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=\\frac{m}{2}\\)</span>.</span></li><li>להניח שבטענה <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> משום <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)-x &gt; 0\\)</span></span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> הרי &quot;האינפימום חיובי&quot;: בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span> המכוסה ברציפות הפונקציה יכולה להגיע <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f(b)=b\\)</span></span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf_{(a,b)}(f(x)-x) = 0\\)</span>.</span></span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/8/q6\">2021א · מועד 81, שאלה 6</a></p>","mc":{"1":true,"2":false}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(-1 &lt; x &lt; 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\arcsin x + \\sqrt{1-x^2} \\ge 1\\)</span>.</span></p>\n<p>א. הטענה נכונה.</p>\n<p>ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הטענה נכונה — נגזרת הביטוי היא פשוט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>,</span> שמשנה סימן משלילי לחיובי באפס, ולכן המינימום מתקבל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> ושם הערך הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הטענה נכונה — נגזרת הביטוי היא פשוט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>,</span> שמשנה סימן משלילי לחיובי באפס, ולכן המינימום מתקבל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> ושם הערך הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: הביטוי נראה מפחיד ממבט ראשון, אבל כשגוזרים אותו קורה נס אלגברי: האיבר המכוער עם השורש מצטמצם בדיוק עם הנגזרת של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>,</span> ונשארת רק נגזרת נקייה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>.</span> משמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> הנגזרת שלילית (הגרף יורד), מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> היא חיובית (הגרף עולה), ולכן בתחתית הקערה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> יושב הערך הקטן ביותר: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0 + \\sqrt{1} = 1\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\cdot 0+\\sqrt{1}=1\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\cdot \\frac{\\pi}{6} + \\frac{\\sqrt{3}}{2} \\approx 0.262 + 0.866 = 1.128 \\ge 1\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.5\\)</span>:</span></span> תוצאה זהה <span class=\"math math-inline\" dir=\"ltr\">\\(\\approx 1.128 \\ge 1\\)</span> כי הפונקציה זוגית.</p>\n<p><strong>פונקציה עם נגזרת שמשנה סימן ממינוס לפלוס</strong> בנקודה אחת <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>)</span> מקבלת שם <strong>מינימום מוחלט</strong> על כל הקטע הפתוח (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x\\arcsin x + \\sqrt{1-x^2}\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span> — צורת קערה סימטרית שיורדת עד הקו האדום המקווקו <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> בנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ועולה בחזרה משני הצדדים.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1.2,&quot;xmax&quot;:1.2,&quot;ymin&quot;:0.7,&quot;ymax&quot;:1.8}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;h&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;h(x)=x\\\\arcsin(x)+\\\\sqrt{1-x^{2}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;y1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;m&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0, 1)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: תגזרו ותראו את הצמצום","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: תגזרו ותראו את הצמצום</p><div class=\"callout-body\"><p>סמנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x\\arcsin x+\\sqrt{1-x^2}\\)</span>.</span> חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)\\)</span> בעזרת כלל המכפלה וכלל השרשרת.</p></div></div>"},{"title":"רמז 2: סימן של $\\arcsin x$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: סימן של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span></p><div class=\"callout-body\"><p>איפה <span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=\\arcsin x\\)</span> שלילית ואיפה היא חיובית בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x\\arcsin x + \\sqrt{1-x^2}\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span>,</span> נגזור בעזרת משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(7.12, 7.21, 7.28\\)</span> ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=\\arcsin x\\)</span>.</span> נסיק ממשפט <span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span> <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> יורדת ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((-1,0]\\)</span></span> ועולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1)\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)\\ge h(0)=1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(-1,1)\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: גזירה ופישוט.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = x\\arcsin x + \\sqrt{1-x^2}\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 1)\\)</span>.</span> בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((-1, 1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-x^2 &gt; 0\\)</span>,</span> ולכן גם <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{1-x^2}\\)</span> גזירות (משפטים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28, 7.21, 7.31\\)</span>).</span> מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> גזירה (ורציפה, משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span>,</span> ונגזרתה לפי כלל המכפלה (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.12\\)</span>)</span> וכלל השרשרת (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.21\\)</span>)</span> היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x) = 1\\cdot\\arcsin x + x\\cdot\\frac{1}{\\sqrt{1-x^2}} + \\frac{-2x}{2\\sqrt{1-x^2}} = \\arcsin x.\\]</div>\n<p><em>למה?</em> שני האיברים עם השורש מבטלים זה את זה במדויק, ונשארת רק פונקציה מונוטונית אחת מוכרת שקל לקרוא את הסימן שלה.</p>\n<p><strong>שלב 2: תחומי עלייה וירידה ומציאת המינימום המוחלט.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([-1,1]\\)</span></span> (או שנגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}&gt;0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin 0 = 0\\)</span>.</span></span> לכן:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 0)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) = \\arcsin x &lt; 0\\)</span>.</span></li><li><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x = 0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = 0\\)</span>.</span></li><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0, 1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) = \\arcsin x &gt; 0\\)</span>.</span></li></ul>\n<p>לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span> (מונוטוניות מסימן הנגזרת, יחד עם הרציפות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> יורדת ממש בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((-1, 0]\\)</span> ועולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0, 1)\\)</span>.</span> לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 1)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) \\ge h(0) = 0\\cdot\\arcsin 0 + \\sqrt{1 - 0^2} = 1.\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\arcsin x + \\sqrt{1-x^2} \\ge 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1 &lt; x &lt; 1\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: א.</p></div></div>","steps":["<p><strong>שלב 1: גזירה ופישוט.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(h(x) = x\\arcsin x + \\sqrt{1-x^2}\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 1)\\)</span>.</span> בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((-1, 1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-x^2 &gt; 0\\)</span>,</span> ולכן גם <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{1-x^2}\\)</span> גזירות (משפטים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.28, 7.21, 7.31\\)</span>).</span> מכאן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span></span> גזירה (ורציפה, משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.9\\)</span>)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span>,</span> ונגזרתה לפי כלל המכפלה (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.12\\)</span>)</span> וכלל השרשרת (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(7.21\\)</span>)</span> היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h'(x) = 1\\cdot\\arcsin x + x\\cdot\\frac{1}{\\sqrt{1-x^2}} + \\frac{-2x}{2\\sqrt{1-x^2}} = \\arcsin x.\\]</div>\n<p><em>למה?</em> שני האיברים עם השורש מבטלים זה את זה במדויק, ונשארת רק פונקציה מונוטונית אחת מוכרת שקל לקרוא את הסימן שלה.</p>","<p><strong>שלב 2: תחומי עלייה וירידה ומציאת המינימום המוחלט.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> עולה ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([-1,1]\\)</span></span> (או שנגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}&gt;0\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin 0 = 0\\)</span>.</span></span> לכן:</p>\n<ul><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 0)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) = \\arcsin x &lt; 0\\)</span>.</span></li><li><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x = 0\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(0) = 0\\)</span>.</span></li><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (0, 1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x) = \\arcsin x &gt; 0\\)</span>.</span></li></ul>\n<p>לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(8.18\\)</span> (מונוטוניות מסימן הנגזרת, יחד עם הרציפות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> יורדת ממש בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((-1, 0]\\)</span> ועולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0, 1)\\)</span>.</span> לפיכך לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x \\in (-1, 1)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[h(x) \\ge h(0) = 0\\cdot\\arcsin 0 + \\sqrt{1 - 0^2} = 1.\\]</div>\n<p>כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\arcsin x + \\sqrt{1-x^2} \\ge 1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1 &lt; x &lt; 1\\)</span>.</span></p>\n<p><strong>התשובה במבחן</strong>: א.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>טעות בסימן בנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{1-x^2}\\)</span> (לשכוח את <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(-2x\\)</span></span> מכלל השרשרת ולהפסיד את הצמצום).</li><li>להסתמך רק על <span class=\"math math-inline\" dir=\"ltr\">\\(h'(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h''(0)=1&gt;0\\)</span>:</span></span> זה נותן מינימום <strong>מקומי</strong> בלבד (משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(8.23\\)</span>),</span> ובלי לבדוק את סימן <span class=\"math math-inline\" dir=\"ltr\">\\(h'\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((-1,0)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> לא מוכיחים אי-שוויון גלובלי בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span>.</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/7/q8\">2020ג · מועד 93, שאלה 8</a></p>","mc":{"answer":"א"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה חסומה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a, b+\\delta)\\)</span> ועולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a, b)\\)</span>.</span> אז:</p>\n<p>א. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-} f(x) \\le f(b)\\)</span>.</span></p>\n<p>ב. אם <span class=\"math math-inline\" dir=\"ltr\">\\(x=b\\)</span> נקודת אי רציפות של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אז היא בהכרח מסוג ראשון.</p>\n<p>ג. אין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> נקודות אי רציפות מסוג שני בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></p>\n<p>ד. אם קיים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מינימום בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min f([a,b]) = f(a)\\)</span>.</span></p>\n<p>ה. כל הטענות הנ״ל אינן נכונות.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בתוך הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> הפונקציה מונוטונית (עולה), ולכן אין לה שם התנדנדויות פרועות או קפיצות לאינסוף — כל אי-רציפות שם יכולה להיות רק קפיצה פשוטה (סוג ראשון), ואינה יכולה להיות מסוג שני.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בתוך הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> הפונקציה מונוטונית (עולה), ולכן אין לה שם התנדנדויות פרועות או קפיצות לאינסוף — כל אי-רציפות שם יכולה להיות רק קפיצה פשוטה (סוג ראשון), ואינה יכולה להיות מסוג שני.</p>\n<p><strong>תמונה בראש</strong>: שימו לב היטב איפה הפונקציה עולה: <strong>רק</strong> בתוך הקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>!</span> על הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> ועל ההמשך <span class=\"math math-inline\" dir=\"ltr\">\\([b, b+\\delta)\\)</span> לא הבטיחו כלום! <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> עצמה מותר לפונקציה לצנוח למטה (מפיל את א), לקפוץ בצורה פרועה מימין (מפיל את ב), או להיות נמוכה יותר מהערך בקצה <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> (מפיל את ד). אבל בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> עצמו, המונוטוניות משמאל ומימין לכל נקודה מבטיחה שמשני הצדדים שלה יש גבולות סופיים — לכן אין אי-רציפות מסוג שני <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0, b=1, \\delta=1\\)</span>,</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> נשים את הפונקציה העולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span>.</span> כדי להפיל את א ו-ד נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=2\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=0\\)</span></span> (אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min_{[0,1]}f=f(1)=0 \\ne 2=f(0)\\)</span>,</span> וכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-} f(x)=1 &gt; 0=f(1)\\)</span>!).</span> וכדי להפיל את ב נשים מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\left(\\frac{1}{x-1}\\right)\\)</span>,</span> שמתנדנדת בלי גבול מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ולכן עושה את <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> לאי-רציפות מסוג שני.</p>\n<p><strong>אי-רציפות מסוג שני</strong> (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.23\\)</span>)</span> היא נקודה שבה לפחות אחד הגבולות החד-צדדיים אינו קיים (או הוא אינסופי). לפי משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.41\\)</span>,</span></span> לפונקציה מונוטונית בפנים של קטע לעולם אין אי-רציפות מסוג שני.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בדוגמה נגדית לא, ב, ד (בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2)\\)</span>):</span> בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> הקו הכחול <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> עולה ונקי מקפיצות פרועות. אבל מחוץ לפתוח שום דבר אינו כובל אותנו: הנקודה האדומה <span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span> היא תקרה גבוהה במקום מינימום, הנקודה הירוקה <span class=\"math math-inline\" dir=\"ltr\">\\((1,0)\\)</span> שוברת את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)\\le f(1)\\)</span> ולוקחת את המינימום לעצמה, והתנודה הכתומה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin(\\frac{1}{x-1})\\)</span> מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> הופכת את <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> לסוג שני.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:1.8,&quot;ymin&quot;:-1.5,&quot;ymax&quot;:2.6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x+0\\\\cdot\\\\sqrt{x\\\\cdot(1-x)}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;f2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\sin(\\\\frac{1}{x-1})+0\\\\cdot\\\\ln(x-1)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;},{&quot;id&quot;:&quot;pb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1, 0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0, 2)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קראו בדיוק איזה קטע פתוח ואיזה חצי-פתוח","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קראו בדיוק איזה קטע פתוח ואיזה חצי-פתוח</p><div class=\"callout-body\"><p><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b+\\delta)\\)</span>,</span></span> אך <strong>עולה רק בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></strong>! מה קורה בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> ובקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b, b+\\delta)\\)</span>?</span></p></div></div>"},{"title":"רמז 2: שימוש במשפט מונוטוניות בתוך קטע","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש במשפט מונוטוניות בתוך קטע</p><div class=\"callout-body\"><p>משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> (ומסקנה <span class=\"math math-inline\" dir=\"ltr\">\\(5.40\\)</span> / משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.41\\)</span>)</span> אומרים שלפונקציה עולה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> קיימים גבולות סופיים משני הצדדים בכל נקודה פנימית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in (a,b)\\)</span>.</span> איזה סוג של אי-רציפות נפסל מכך מיידית?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את טענה ג בעזרת משפטים <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.41\\)</span>:</span></span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\in(a,b)\\)</span> קיימים הגבולות החד-צדדיים סופיים של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> ולכן אינה יכולה להיות שם אי-רציפות מסוג שני. לאחר מכן נפריך את א, ב, ו-ד על ידי דוגמאות נגד המנצלות את העובדה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה כבולה למונוטוניות בנקודות הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\)</span> <span class=\"nobr\">וב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b,b+\\delta)\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הוכחת טענה ג.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> עולה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a, b)\\)</span>.</span> לכל נקודה פנימית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in (a, b)\\)</span>:</span> לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> (גבולות חד-צדדיים של פונקציה מונוטונית, שכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((a,x_0)\\)</span> ובכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_0,b)\\)</span>,</span> או אף פשוט מעצם המונוטוניות משני צדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(a_1)\\le f(x)\\le f(x_0)\\)</span> משמאל <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\le f(x)\\le f(b_1)\\)</span></span> מימין), קיימים שני הגבולות החד-צדדיים הסופיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^-} f(x)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^+} f(x)\\)</span></span> (והם אף מקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^-} f(x) \\le f(x_0) \\le \\lim_{x\\to x_0^+} f(x)\\)</span>,</span> משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.41\\)</span>).</span> מכיוון שאי-רציפות מסוג שני (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.23\\)</span>)</span> מוגדרת כמצב שבו לפחות אחד הגבולות החד-צדדיים אינו קיים במובן הסופי, לא קיימת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אף נקודת אי-רציפות מסוג שני בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span> לכן טענה ג נכונה.</p>\n<p><em>למה?</em> בין אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בנקודה שבתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> ובין אם היא קופצת שם למעלה, המונוטוניות מונעת ממנה לזגזג או לברוח לאינסוף לפני ואחרי הנקודה — כך ששני הגבולות החד-צדדיים תמיד קיימים וסופיים.</p>\n<p><strong>שלב 2: שלילת טענות א, ב, ו-ד (על הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0, 2)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0, b=1, \\delta=1\\)</span>).</span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f: [0, 2) \\to \\mathbb{R}\\)</span> כך:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) = \\begin{cases} 2 &amp; x = 0 \\\\ x &amp; 0 &lt; x &lt; 1 \\\\ 0 &amp; x = 1 \\\\ \\sin\\left(\\frac{1}{x-1}\\right) &amp; 1 &lt; x &lt; 2. \\end{cases}\\]</div>\n<p>הפונקציה חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0, 2)\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)| \\le 2\\)</span>)</span> ועולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0, 1)\\)</span>,</span></span> ולכן עומדת בכל תנאי השאלה:</p>\n<ul><li><strong>הפרכת א</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-} f(x) = 1 &gt; 0 = f(1)\\)</span>,</span> בסתירה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-} f(x) \\le f(1)\\)</span>.</span></span></li><li><strong>הפרכת ב</strong>: <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין גבול <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x \\to 1^+\\)</span></span> כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\left(\\frac{1}{x-1}\\right)\\)</span> מתנודדת בין <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בכל סביבה ימנית של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> היא נקודת אי-רציפות <strong>מסוג שני</strong>, ולא מסוג ראשון.</li><li><strong>הפרכת ד</strong>: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> הפונקציה מקבלת את ערכה המינימלי <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span> ואילו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0) = 2 \\ne 0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min f([0,1]) = 0 \\ne f(0)\\)</span>.</span></span></li></ul>\n<p>(ממילא מאחר ש-ג נכונה, טענה ה שגויה.)</p>\n<p><strong>התשובה במבחן</strong>: ג.</p></div></div>","steps":["<p><strong>שלב 1: הוכחת טענה ג.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> עולה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a, b)\\)</span>.</span> לכל נקודה פנימית <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0 \\in (a, b)\\)</span>:</span> לפי משפט <span class=\"math math-inline\" dir=\"ltr\">\\(5.39\\)</span> (גבולות חד-צדדיים של פונקציה מונוטונית, שכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((a,x_0)\\)</span> ובכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_0,b)\\)</span>,</span> או אף פשוט מעצם המונוטוניות משני צדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(a_1)\\le f(x)\\le f(x_0)\\)</span> משמאל <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\le f(x)\\le f(b_1)\\)</span></span> מימין), קיימים שני הגבולות החד-צדדיים הסופיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^-} f(x)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^+} f(x)\\)</span></span> (והם אף מקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0^-} f(x) \\le f(x_0) \\le \\lim_{x\\to x_0^+} f(x)\\)</span>,</span> משפט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.41\\)</span>).</span> מכיוון שאי-רציפות מסוג שני (הגדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(5.23\\)</span>)</span> מוגדרת כמצב שבו לפחות אחד הגבולות החד-צדדיים אינו קיים במובן הסופי, לא קיימת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אף נקודת אי-רציפות מסוג שני בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span> לכן טענה ג נכונה.</p>\n<p><em>למה?</em> בין אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בנקודה שבתוך <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> ובין אם היא קופצת שם למעלה, המונוטוניות מונעת ממנה לזגזג או לברוח לאינסוף לפני ואחרי הנקודה — כך ששני הגבולות החד-צדדיים תמיד קיימים וסופיים.</p>","<p><strong>שלב 2: שלילת טענות א, ב, ו-ד (על הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0, 2)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0, b=1, \\delta=1\\)</span>).</span></strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f: [0, 2) \\to \\mathbb{R}\\)</span> כך:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x) = \\begin{cases} 2 &amp; x = 0 \\\\ x &amp; 0 &lt; x &lt; 1 \\\\ 0 &amp; x = 1 \\\\ \\sin\\left(\\frac{1}{x-1}\\right) &amp; 1 &lt; x &lt; 2. \\end{cases}\\]</div>\n<p>הפונקציה חסומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0, 2)\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)| \\le 2\\)</span>)</span> ועולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0, 1)\\)</span>,</span></span> ולכן עומדת בכל תנאי השאלה:</p>\n<ul><li><strong>הפרכת א</strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-} f(x) = 1 &gt; 0 = f(1)\\)</span>,</span> בסתירה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-} f(x) \\le f(1)\\)</span>.</span></span></li><li><strong>הפרכת ב</strong>: <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין גבול <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x \\to 1^+\\)</span></span> כי <span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\left(\\frac{1}{x-1}\\right)\\)</span> מתנודדת בין <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> בכל סביבה ימנית של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> היא נקודת אי-רציפות <strong>מסוג שני</strong>, ולא מסוג ראשון.</li><li><strong>הפרכת ד</strong>: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> הפונקציה מקבלת את ערכה המינימלי <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span> ואילו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0) = 2 \\ne 0\\)</span>,</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\min f([0,1]) = 0 \\ne f(0)\\)</span>.</span></span></li></ul>\n<p>(ממילא מאחר ש-ג נכונה, טענה ה שגויה.)</p>\n<p><strong>התשובה במבחן</strong>: ג.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להניח ש-&quot;עולה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>&quot; פירושו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> עולה על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> ואפילו על <span class=\"math math-inline\" dir=\"ltr\">\\([a, b+\\delta)\\)</span> — הקטע שבו ניתנה העלייה הוא הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> בלבד!</li><li>לטעות בטענה ב ולחשוב שאם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> עולה לפני <span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span> וחסומה מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> אז יש לה גבול מימין <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>;</span></span> חסימות אינה מונעת תנודות כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\left(\\frac{1}{x-b}\\right)\\)</span>.</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/8/q8\">2021א · מועד 81, שאלה 8</a></p>","mc":{"answer":"ג"}}};
